export function CallPanel({
  currentUser,
}: {
  currentUser: { id: string; name: string; image?: string | null }
}) {
  const {
    activeCall,
    incoming,
    acceptIncomingCall,
    rejectIncomingCall,
    cancelOutgoingCall,
    endCall,
  } = useCallContext()

