              </div>

              <p className="text-[13px] font-medium text-white/50">
                <span className="font-semibold text-white/80">{incoming.callerName}</span>
                {incoming.callType === 'video' ? ' te está llamando por videollamada...' : ' te está llamando...'}
              </p>

              <motion.div
                initial={{ y: 16, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ type: 'spring', stiffness: 320, damping: 26, delay: 0.12 }}
                className="flex items-center gap-3"
              >
                {incoming.callType === 'video' && (
                  <button
                    onClick={acceptIncomingCall}
                    title="Aceptar con video"
                    className="flex h-12 w-16 items-center justify-center rounded-xl bg-[#1a6334] text-white shadow-lg transition-all hover:bg-[#23a55a] hover:scale-105 active:scale-95"
                  >
                    <Video className="size-5" />
                  </button>
                )}
                <button
                  onClick={acceptIncomingCall}
                  title="Aceptar"
                  className="flex h-12 w-16 items-center justify-center rounded-xl bg-[#23a55a] text-white shadow-lg transition-all hover:bg-[#1a8045] hover:scale-105 active:scale-95"
                >
                  <Phone className="size-5" />
                </button>
                <button
                  onClick={rejectIncomingCall}
                  title="Rechazar"
                  className="flex h-12 w-16 items-center justify-center rounded-xl bg-[#da373c] text-white shadow-lg transition-all hover:bg-[#a12828] hover:scale-105 active:scale-95"
                >
                  <X className="size-5" />
                </button>
              </motion.div>
            </div>
          )}

          {/* Outgoing ringing */}
          {(activeCall?.state === 'outgoing-ringing' || activeCall?.state === 'no-answer') && (
            <div className="flex h-[240px] flex-col items-center justify-center gap-5">
              <div className="flex items-center gap-4">
                <motion.div
                  initial={{ scale: 0.6, opacity: 0 }}
                  animate={{ scale: 1, opacity: 1 }}
                  transition={{ type: 'spring', stiffness: 300, damping: 24 }}
                >
                  <Avatar name={currentUser.name} image={currentUser.image} />
                </motion.div>
                <motion.div
                  initial={{ scale: 0.6, opacity: 0 }}
                  animate={{ scale: 1, opacity: 1 }}
                  transition={{ type: 'spring', stiffness: 300, damping: 24, delay: 0.08 }}
                >
                  <Avatar
                    name={activeCall.peerName}
                    image={activeCall.peerImage}
                    pulse={activeCall.state === 'outgoing-ringing'}
                    dim={activeCall.state === 'no-answer'}
                    ring
                  />
                </motion.div>
              </div>

              <p className="calling-dots text-[13px] font-medium text-white/50">
                {activeCall.state === 'no-answer' ? (
                  <>
                    <span className="font-semibold text-white/80">{activeCall.peerName}</span> no contestó
                  </>
                ) : (
                  <>
                    Llamando a <span className="font-semibold text-white/80">{activeCall.peerName}</span>
                    <span>.</span>
                    <span>.</span>
                    <span>.</span>
                  </>
                )}
              </p>

              <motion.button
                initial={{ y: 16, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ type: 'spring', stiffness: 320, damping: 26, delay: 0.12 }}
                onClick={cancelOutgoingCall}
                title="Cancelar llamada"
                className="flex h-12 w-20 items-center justify-center rounded-xl bg-[#da373c] text-white shadow-lg transition-all hover:bg-[#a12828] hover:scale-105 active:scale-95"
              >
                <Phone className="size-5 rotate-[135deg]" />
              </motion.button>
            </div>
          )}

          {/* In-call — embedded LiveKit stage */}
          {activeCall?.state === 'in-call' && activeCall.token && activeCall.livekitUrl && (
            <LiveKitRoom
              token={activeCall.token}
              serverUrl={activeCall.livekitUrl}
              connect
              audio
              video={
                activeCall.callType === 'video'
                  ? { resolution: { width: 1920, height: 1080, frameRate: 60 } }
                  : false
              }
              data-lk-theme="default"
              onDisconnected={endCall}
              className="block w-full"
              style={{ backgroundColor: '#000000' }}
            >
              <InCallStage
                peerName={activeCall.peerName}
                peerImage={activeCall.peerImage}
                selfName={currentUser.name}
                selfImage={currentUser.image}
                onHangUp={endCall}
              />
            </LiveKitRoom>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  )
}

'use client'

import React, { createContext, useCallback, useContext, useEffect, useRef, useState } from 'react'
import type { Room } from 'livekit-client'
import { subscribeIncomingCalls, createCallChannel, broadcastCallInvite, subscribeAndWait, sendCallSignal } from '@/lib/calls/signaling'
import { supabase } from '@/lib/supabase/client'
import type { ActiveCall, CallType, CallInvitePayload } from '@/lib/calls/types'
import type { AppUser } from '@/components/chat-app'

export interface IncomingCall {
  callId: string
  conversationId: number
  callType: CallType
  callerId: string
  callerName: string
  callerImage: string | null
}

interface CallContextValue {
  activeCall: ActiveCall | null
  incoming: IncomingCall | null
  startOutgoingCall: (convId: number, type: CallType, calleeId: string, calleeName: string, calleeImage?: string | null) => void
  cancelOutgoingCall: () => void
  acceptIncomingCall: () => void
  rejectIncomingCall: () => void
  endCall: () => void
  room: Room | null
  setRoom: (room: Room | null) => void
}

const CallContext = createContext<CallContextValue | null>(null)

export function useCallContext() {
  const ctx = useContext(CallContext)
  if (!ctx) throw new Error('useCallContext must be used within CallProvider')
  return ctx
}

export function CallProvider({
  user,
  children,
}: {
  user: AppUser
  children: React.ReactNode
}) {
  const [activeCall, setActiveCall] = useState<ActiveCall | null>(null)
  const [incoming, setIncoming] = useState<IncomingCall | null>(null)
  const [room, setRoom] = useState<Room | null>(null)
  const [channel, setChannel] = useState<ReturnType<typeof createCallChannel> | null>(null)
  const ringTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const incomingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => {
    const unsub = subscribeIncomingCalls(user.id, (payload: CallInvitePayload) => {
      if (activeCall) {
        return
      }
      setIncoming({
        callId: payload.callId,
        conversationId: payload.conversationId,
        callType: payload.callType,
        callerId: payload.from,
        callerName: payload.fromName,
        callerImage: null,
      })
    })

    return () => unsub()
  }, [user.id, activeCall])

  // Auto-dismiss incoming call after 30s
  useEffect(() => {
    if (incomingTimeoutRef.current) {
      clearTimeout(incomingTimeoutRef.current)
      incomingTimeoutRef.current = null
    }
    if (incoming) {
      incomingTimeoutRef.current = setTimeout(() => {
        setIncoming(null)
      }, 30000)
    }
    return () => {
      if (incomingTimeoutRef.current) clearTimeout(incomingTimeoutRef.current)
    }
  }, [incoming])

  const startOutgoingCall = useCallback(
    async (convId: number, type: CallType, calleeId: string, calleeName: string, calleeImage?: string | null) => {
      const callId = crypto.randomUUID()
      setActiveCall({
        callId,
        conversationId: convId,
        callType: type,
        state: 'outgoing-ringing',
        peerName: calleeName,
        peerImage: calleeImage ?? null,
      })

      await broadcastCallInvite(
        {
          from: user.id,
          fromName: user.name,
          callId,
          conversationId: convId,
          callType: type,
        },
        calleeId,
      )

      const chan = createCallChannel(convId)
      await subscribeAndWait(chan)
      setChannel(chan)

      chan
        .on('broadcast', { event: 'call:accept' }, async () => {
          if (ringTimeoutRef.current) {
            clearTimeout(ringTimeoutRef.current)
            ringTimeoutRef.current = null
          }
          await fetchTokenAndJoin(callId, convId, type, calleeName, calleeImage ?? null)
        })
        .on('broadcast', { event: 'call:decline' }, () => {
          if (ringTimeoutRef.current) {
            clearTimeout(ringTimeoutRef.current)
            ringTimeoutRef.current = null
          }
          try { supabase.removeChannel(chan) } catch {}
          setActiveCall(null)
          setChannel(null)
        })
        .on('broadcast', { event: 'call:cancel' }, () => {
          if (ringTimeoutRef.current) {
            clearTimeout(ringTimeoutRef.current)
            ringTimeoutRef.current = null
          }
          try { supabase.removeChannel(chan) } catch {}
          setActiveCall(null)
          setChannel(null)
        })

      ringTimeoutRef.current = setTimeout(() => {
        setActiveCall((prev) => prev?.state === 'outgoing-ringing' ? { ...prev, state: 'no-answer' } : null)
        setTimeout(() => {
          try { supabase.removeChannel(chan) } catch {}
          setActiveCall(null)
          setChannel(null)
        }, 2500)
        ringTimeoutRef.current = null
      }, 30000)
      setChannel(chan)
    },
    [user.id, user.name],
  )

  const fetchTokenAndJoin = useCallback(
    async (callId: string, convId: number, type: CallType, peerName: string, peerImage: string | null) => {
      try {
        const res = await fetch('/api/livekit/token', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ conversationId: convId }),
        })
        if (!res.ok) throw new Error('Token fetch failed')
        const { token, url } = await res.json()
        setActiveCall({
          callId,
          conversationId: convId,
          callType: type,
          state: 'in-call',
          peerName,
          peerImage,
          token,
          livekitUrl: url,
        })
      } catch {
        setActiveCall(null)
        setChannel(null)
      }
    },
    [],
  )

  const acceptIncomingCall = useCallback(async () => {
    if (!incoming) return

    const chan = createCallChannel(incoming.conversationId)
    await subscribeAndWait(chan)
    setChannel(chan)

    await sendCallSignal(chan, 'call:accept', {
      from: user.id,
      callId: incoming.callId,
    })

    await fetchTokenAndJoin(
      incoming.callId,
      incoming.conversationId,
      incoming.callType,
      incoming.callerName,
      incoming.callerImage,
    )
    setIncoming(null)
  }, [incoming, user.id, fetchTokenAndJoin])

  const rejectIncomingCall = useCallback(async () => {
    if (!incoming) return
    const chan = createCallChannel(incoming.conversationId)
    await subscribeAndWait(chan)
    await sendCallSignal(chan, 'call:decline', {
      from: user.id,
      callId: incoming.callId,
    })
    try { supabase.removeChannel(chan) } catch {}
    setIncoming(null)
  }, [incoming, user.id])

  const cancelOutgoingCall = useCallback(() => {
    if (channel) {
      sendCallSignal(channel, 'call:cancel', { from: user.id }).catch(() => {})
      try { supabase.removeChannel(channel) } catch {}
    }
    if (ringTimeoutRef.current) {
      clearTimeout(ringTimeoutRef.current)
      ringTimeoutRef.current = null
    }
    setActiveCall(null)
    setChannel(null)
  }, [channel, user.id])

  const endCall = useCallback(() => {
    if (room) {
      try { room.disconnect() } catch {}
    }
    if (channel) {
      try { supabase.removeChannel(channel) } catch {}
    }
    setActiveCall(null)
    setChannel(null)
    setRoom(null)
  }, [room, channel])

  return (
    <CallContext.Provider
      value={{
        activeCall,
        incoming,
        startOutgoingCall,
        cancelOutgoingCall,
        acceptIncomingCall,
        rejectIncomingCall,
        endCall,
        room,
        setRoom,
      }}
    >
      {children}
    </CallContext.Provider>
  )
}

'use client'

import { motion, AnimatePresence } from 'framer-motion'
import { X, Monitor, AppWindow, MonitorUp } from 'lucide-react'
import { useEffect, useMemo, useState } from 'react'

interface ScreenSource {
  id: string
  name: string
  thumbnail: string
}

export function ScreenPicker() {
  const [open, setOpen] = useState(false)
  const [sources, setSources] = useState<ScreenSource[]>([])
  const [tab, setTab] = useState<'screens' | 'windows'>('screens')
  const [selected, setSelected] = useState<string | null>(null)

  useEffect(() => {
    const api = (window as any).screenShare as
      | { onSources: (cb: (s: ScreenSource[]) => void) => () => void; select: (id: string | null) => Promise<void> }
      | undefined

    if (!api) return

    const unsub = api.onSources((s: ScreenSource[]) => {
      console.log('[ScreenPicker] sources received:', s.length)
      setSources(s)
      setSelected(null)
      setTab('screens')
      setOpen(true)
    })
    return () => unsub()
  }, [])

  const screens = useMemo(() => sources.filter((s) => s.id.startsWith('screen')), [sources])
  const windows = useMemo(() => sources.filter((s) => !s.id.startsWith('screen')), [sources])
  const visibleSources = tab === 'screens' ? screens : windows

  const handleShare = async () => {
    if (!selected) return
    const api = (window as any).screenShare
    if (api) await api.select(selected)
    setOpen(false)
    setSources([])
    setSelected(null)
  }

  const handleCancel = () => {
    const api = (window as any).screenShare
    if (api) api.select(null).catch(() => {})
    setOpen(false)
    setSources([])
    setSelected(null)
  }

  const isElectron = typeof window !== 'undefined' && 'screenShare' in window
  if (!isElectron) return null

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-md"
          onClick={handleCancel}
        >
          <motion.div
            initial={{ scale: 0.94, y: 24, opacity: 0 }}
            animate={{ scale: 1, y: 0, opacity: 1 }}
            exit={{ scale: 0.94, y: 24, opacity: 0 }}
            transition={{ type: 'spring', stiffness: 320, damping: 28 }}
            onClick={(e) => e.stopPropagation()}
            className="flex max-h-[80vh] w-full max-w-2xl flex-col overflow-hidden rounded-2xl border border-white/10 bg-[#111214] shadow-2xl"
          >
            {/* Header */}
            <div className="flex items-center justify-between border-b border-white/[0.06] px-6 py-4">
              <div className="flex items-center gap-3">
                <span className="flex size-9 items-center justify-center rounded-xl bg-[#23a55a]/15 text-[#23a55a]">
                  <MonitorUp className="size-4.5" />
                </span>
                <div>
                  <h2 className="text-[15px] font-semibold text-white">Compartir pantalla</h2>
                  <p className="text-[12px] text-white/40">Elige qué quieres compartir en la llamada</p>
                </div>
              </div>
              <button
                onClick={handleCancel}
                aria-label="Cerrar"
                className="rounded-lg p-1.5 text-white/40 transition-colors hover:bg-white/10 hover:text-white"
              >
                <X className="size-5" />
              </button>
            </div>

            {/* Tabs */}
            <div className="flex gap-1 px-6 pt-4">
              <button
                onClick={() => setTab('screens')}
                className={`relative flex items-center gap-2 rounded-lg px-3.5 py-2 text-[13px] font-medium transition-colors ${
                  tab === 'screens' ? 'text-white' : 'text-white/40 hover:text-white/70'
                }`}
              >
                {tab === 'screens' && (
                  <motion.span
                    layoutId="screen-picker-tab"
                    className="absolute inset-0 rounded-lg bg-white/10"
                    transition={{ type: 'spring', stiffness: 400, damping: 32 }}
                  />
                )}
                <Monitor className="relative size-4" />
                <span className="relative">Pantallas</span>
                <span className="relative rounded-full bg-white/10 px-1.5 py-px text-[10px] text-white/50">
                  {screens.length}
                </span>
              </button>
              <button
                onClick={() => setTab('windows')}
                className={`relative flex items-center gap-2 rounded-lg px-3.5 py-2 text-[13px] font-medium transition-colors ${
                  tab === 'windows' ? 'text-white' : 'text-white/40 hover:text-white/70'
                }`}
              >
                {tab === 'windows' && (
                  <motion.span
                    layoutId="screen-picker-tab"
                    className="absolute inset-0 rounded-lg bg-white/10"
                    transition={{ type: 'spring', stiffness: 400, damping: 32 }}
                  />
                )}
                <AppWindow className="relative size-4" />
                <span className="relative">Aplicaciones</span>
                <span className="relative rounded-full bg-white/10 px-1.5 py-px text-[10px] text-white/50">
                  {windows.length}
                </span>
              </button>
            </div>

            {/* Grid */}
            <div className="thin-scroll grid flex-1 grid-cols-2 gap-3 overflow-y-auto p-6 sm:grid-cols-3">
              {sources.length === 0 && (
                <p className="col-span-full py-10 text-center text-sm text-white/40">Cargando fuentes...</p>
              )}
              {sources.length > 0 && visibleSources.length === 0 && (
                <p className="col-span-full py-10 text-center text-sm text-white/40">
                  {tab === 'screens' ? 'No hay pantallas disponibles' : 'No hay ventanas disponibles'}
                </p>
              )}
              {visibleSources.map((source, i) => {
                const isSelected = selected === source.id
                return (
                  <motion.button
                    key={source.id}
                    initial={{ opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: i * 0.04, duration: 0.25, ease: 'easeOut' }}
                    onClick={() => setSelected(source.id)}
                    onDoubleClick={handleShare}
                    className={`group flex flex-col gap-2 rounded-xl border-2 p-2 text-left transition-all ${
                      isSelected
                        ? 'border-[#23a55a] bg-[#23a55a]/10'
                        : 'border-transparent bg-white/[0.04] hover:bg-white/[0.08]'
                    }`}
                  >
                    <div className="relative w-full overflow-hidden rounded-lg bg-black/50" style={{ aspectRatio: '16/10' }}>
                      {source.thumbnail ? (
                        <img
                          src={source.thumbnail || '/placeholder.svg'}
                          alt={source.name}
                          className="size-full object-cover transition-transform duration-200 group-hover:scale-[1.03]"
                        />
                      ) : (
                        <div className="flex size-full items-center justify-center text-white/20">
                          {tab === 'screens' ? <Monitor className="size-8" /> : <AppWindow className="size-8" />}
                        </div>
                      )}
                      {isSelected && (
                        <span className="absolute right-1.5 top-1.5 flex size-5 items-center justify-center rounded-full bg-[#23a55a] text-white">
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="size-3">
                            <path d="M20 6 9 17l-5-5" strokeLinecap="round" strokeLinejoin="round" />
                          </svg>
                        </span>
                      )}
                    </div>
                    <span className={`truncate px-1 text-[12px] font-medium ${isSelected ? 'text-white' : 'text-white/60'}`}>
                      {source.name}
                    </span>
                  </motion.button>
                )
              })}
            </div>

            {/* Footer */}
            <div className="flex items-center justify-end gap-2.5 border-t border-white/[0.06] px-6 py-4">
              <button
                onClick={handleCancel}
                className="rounded-lg px-4 py-2 text-[13px] font-medium text-white/60 transition-colors hover:bg-white/5 hover:text-white"
              >
                Cancelar
              </button>
              <button
                onClick={handleShare}
                disabled={!selected}
                className="rounded-lg bg-[#23a55a] px-5 py-2 text-[13px] font-semibold text-white shadow-lg transition-all hover:bg-[#1a8045] active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-40"
              >
                Compartir
              </button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

'use client'

import React, { useState } from 'react'
import { Heart, Pause, Play, SkipBack, SkipForward, Music, X } from 'lucide-react'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'

export function CatMusicDockWidget({ onOpenCatMusic }: { onOpenCatMusic?: () => void }) {
  const player = useCatMusicPlayer()
  const library = useLibrary()
  // Hooks must run before any early return, so this stays above the guards below.
  const [closing, setClosing] = useState(false)

  if (!player || !library || !player.currentTrack) return null

  const { currentTrack, playerState, togglePlayPause, nextTrack, previousTrack, stopPlayback } = player
  const { isFavorite, toggleFavorite } = library

  const isPlaying = playerState.isPlaying
  const fav = isFavorite(currentTrack.id)
  const pos = playerState.position || 0
  const dur = playerState.duration || 180
  const progressPct = Math.min(100, Math.max(0, (pos / dur) * 100))

  const handleStop = () => {
    setClosing(true)
    setTimeout(() => {
      stopPlayback()
    }, 300)
  }

  return (
    <div className={`w-full border-b border-white/[0.06] px-3 py-2 select-none transition-all duration-300 ${closing ? 'opacity-0 max-h-0 py-0 border-b-0 overflow-hidden' : 'opacity-100'}`}>
      <div className="flex items-center justify-between gap-2 min-w-0">
        {/* Track Artwork */}
        <div
          onClick={onOpenCatMusic}
          className="relative group cursor-pointer size-9 shrink-0 overflow-hidden rounded-lg bg-white/[0.04] shadow-sm"
          title="Abrir CatMusic"
        >
          <img
            src={currentTrack.artworkUrl}
            alt={currentTrack.title}
            className="size-full object-cover"
            onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
          />
          {isPlaying && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/40">
              <span className="flex items-end gap-0.5 h-3">
                <span className="w-0.5 bg-emerald-400 animate-pulse h-3 rounded-full" />
                <span className="w-0.5 bg-emerald-400 animate-pulse h-2 delay-75 rounded-full" />
                <span className="w-0.5 bg-emerald-400 animate-pulse h-3.5 delay-150 rounded-full" />
              </span>
            </div>
          )}
        </div>

        {/* Track Meta */}
        <div onClick={onOpenCatMusic} className="min-w-0 max-w-32 flex-1 cursor-pointer">
          <div className="flex items-center gap-1">
            <Music className="size-3 text-emerald-400 shrink-0" />
            <p className="truncate text-[11.5px] font-bold text-white leading-tight">{currentTrack.title}</p>
          </div>
          <p className="truncate text-[10px] text-white/40 leading-tight mt-0.5">{currentTrack.artist}</p>
        </div>

        {/* Controls */}
        <div className="flex items-center gap-0.5 shrink-0">
          <button
            onClick={() => toggleFavorite(currentTrack)}
            aria-label={fav ? 'Quitar de favoritos' : 'Añadir a favoritos'}
            className={`rounded-md p-1 transition-colors ${
              fav ? 'text-rose-400' : 'text-white/30 hover:text-white/70'
            }`}
          >
            <Heart className={`size-3.5 ${fav ? 'fill-current' : ''}`} />
          </button>

          <button
            onClick={previousTrack}
            aria-label="Anterior"
            className="rounded-md p-1 text-white/40 hover:text-white transition-colors"
          >
            <SkipBack className="size-3.5 fill-current" />
          </button>

          <button
            onClick={togglePlayPause}
            aria-label={isPlaying ? 'Pausar' : 'Reproducir'}
            className="flex size-7 items-center justify-center rounded-full bg-emerald-500 text-black shadow-sm transition-transform hover:scale-105 active:scale-95"
          >
            {isPlaying ? <Pause className="size-3.5 fill-current" /> : <Play className="size-3.5 fill-current ml-0.5" />}
          </button>

          <button
            onClick={nextTrack}
            aria-label="Siguiente"
            className="rounded-md p-1 text-white/40 hover:text-white transition-colors"
          >
            <SkipForward className="size-3.5 fill-current" />
          </button>

          <button
            onClick={handleStop}
            aria-label="Detener"
            className="rounded-md p-1 text-white/25 hover:text-red-400 transition-colors ml-1"
          >
            <X className="size-3" />
          </button>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="mt-1 h-0.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
        <div className="h-full rounded-full bg-emerald-500 transition-all duration-300" style={{ width: `${progressPct}%` }} />
      </div>
    </div>
  )
}

'use client'

import React, { useState, useEffect, useMemo, useRef } from 'react'
import {
  Bell,
  BellOff,
  Clock,
  Heart,
  Home,
  Library,
  ListMusic,
  Maximize2,
  Minimize2,
  Music,
  Plus,
  Radio,
  Search,
  Settings,
  Sparkles,
  Trash2,
  User,
  Play,
  ChevronDown,
  X,
} from 'lucide-react'
import { SEED_TRACKS, GENRES } from '@/lib/plugins/cat-music/catalog'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'
import { useLanguage } from '@/lib/i18n'
import { TrackCard } from './track-card'
import { TrackRow } from './track-row'
import { TrackDetailView } from './track-detail-view'
import { ArtistDetailView } from './artist-detail-view'
import { GlassPanel } from './glass-panel'
import { HomeDashboard } from './home-dashboard'
import type { PluginViewProps } from '@/lib/plugins/plugin-types'
import type { Track } from '@/lib/plugins/cat-music/types'
import type { YtPlaylist, YtChannel } from '@/lib/plugins/cat-music/innertube'
import {
  exitDocumentFullscreen,
  getFullscreenElement,
  requestElementFullscreen,
  subscribeFullscreenChange,
} from '@/lib/fullscreen'

type Tab = 'home' | 'explore' | 'library'
type SearchTab = 'songs' | 'playlists' | 'artists'

function NavButton({
  active,
  onClick,
  icon: Icon,
  label,
}: {
  active: boolean
  onClick: () => void
  icon: React.ElementType
  label: string
}) {
  return (
    <button
      onClick={onClick}
      className={`flex w-full items-center gap-3 rounded-2xl px-3 py-2.5 text-[13px] font-semibold transition-all ${
        active
          ? 'bg-[#1DB954]/20 text-white shadow-inner shadow-[#1DB954]/10'
          : 'text-white/55 hover:bg-white/5 hover:text-white'
      }`}
    >
      <Icon className={`size-4 ${active ? 'text-[#1DB954]' : ''}`} />
      <span>{label}</span>
    </button>
  )
}

export function CatMusicMainView({ onOpenSettings }: PluginViewProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const [activeTab, setActiveTab] = useState<Tab>('home')
  const [searchQuery, setSearchQuery] = useState('')
  const [searchTab, setSearchTab] = useState<SearchTab>('songs')
  const [selectedGenre, setSelectedGenre] = useState('Todos')
  const [newPlaylistOpen, setNewPlaylistOpen] = useState(false)
  const [newPlName, setNewPlName] = useState('')
  const [selectedPlaylistId, setSelectedPlaylistId] = useState<string | null>(null)
  const [songResults, setSongResults] = useState<Track[]>([])
  const [playlistResults, setPlaylistResults] = useState<YtPlaylist[]>([])
  const [channelResults, setChannelResults] = useState<YtChannel[]>([])
  const [isSearching, setIsSearching] = useState(false)
  const [showLibraryPlaylists, setShowLibraryPlaylists] = useState(true)
  const [showNotifications, setShowNotifications] = useState(false)
  const [isFullscreen, setIsFullscreen] = useState(false)
  const [notifPermission, setNotifPermission] = useState<NotificationPermission | 'unsupported'>('default')

  const [selectedTrackDetail, setSelectedTrackDetail] = useState<Track | null>(null)
  const [selectedArtistName, setSelectedArtistName] = useState<string | null>(null)
  const [artistBanner, setArtistBanner] = useState<string>()

  const { playTrack, currentTrack, playerState, togglePlayPause } = useCatMusicPlayer()
  const queue = playerState.queue
  const { favorites, playlists, history, createPlaylist, deletePlaylist, clearHistory } = useLibrary()
  const { t } = useLanguage()

  const featuredTrack = currentTrack ?? SEED_TRACKS[3]

  useEffect(() => {
    const artist = featuredTrack.artist
    if (!artist) return
    fetch(`/api/youtube/channel?name=${encodeURIComponent(artist)}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.channel?.bannerUrl) setArtistBanner(data.channel.bannerUrl)
      })
      .catch(() => {})
  }, [featuredTrack.artist])

  useEffect(() => {
    if (typeof window === 'undefined') return
    setNotifPermission('Notification' in window ? Notification.permission : 'unsupported')
  }, [])

  useEffect(() => {
    return subscribeFullscreenChange(() => {
      const fullEl = getFullscreenElement()
      if (fullEl) {
        setIsFullscreen(true)
      } else {
        setIsFullscreen(false)
      }
    })
  }, [])

  useEffect(() => {
    if (!isFullscreen) return
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsFullscreen(false)
        if (getFullscreenElement()) {
          exitDocumentFullscreen().catch(() => {})
        }
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => {
      document.body.style.overflow = previousOverflow
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [isFullscreen])

  const requestNotifications = async () => {
    if (!('Notification' in window)) return
    const permission = await Notification.requestPermission()
    setNotifPermission(permission)
  }

  const toggleFullscreen = async () => {
    const root = rootRef.current
    if (!root) return

    if (isFullscreen) {
      setIsFullscreen(false)
      if (getFullscreenElement()) {
        try {
          await exitDocumentFullscreen()
        } catch {
          // CSS mode exits via state
        }
      }
      return
    }

    setIsFullscreen(true)
    try {
      await requestElementFullscreen(root)
    } catch {
      // Immersive CSS mode (fixed inset-0 z-[9999]) still applies via isFullscreen state
    }
  }

  useEffect(() => {
    const query = searchQuery.trim()
    if (!query || query.length < 2) {
      setSongResults([])
      setPlaylistResults([])
      setChannelResults([])
      setIsSearching(false)
      return
    }

    setIsSearching(true)
    const timer = setTimeout(async () => {
      try {
        const [songRes, playlistRes, channelRes] = await Promise.all([
          fetch(`/api/youtube/search?q=${encodeURIComponent(query)}&type=video`),
          fetch(`/api/youtube/search?q=${encodeURIComponent(query)}&type=playlist`),
          fetch(`/api/youtube/search?q=${encodeURIComponent(query)}&type=channel`),
        ])
        const [songData, playlistData, channelData] = await Promise.all([
          songRes.ok ? songRes.json() : { results: [] },
          playlistRes.ok ? playlistRes.json() : { results: [] },
          channelRes.ok ? channelRes.json() : { results: [] },
        ])
        setSongResults(songData.results || [])
        setPlaylistResults(playlistData.results || [])
        setChannelResults(channelData.results || [])
      } catch {
        setSongResults([])
        setPlaylistResults([])
        setChannelResults([])
      } finally {
        setIsSearching(false)
      }
    }, 350)

    return () => clearTimeout(timer)
  }, [searchQuery])

  const localFiltered = SEED_TRACKS.filter((t) => {
    const matchesQuery =
      !searchQuery ||
      t.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.artist.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesGenre = selectedGenre === 'Todos' || t.genre === selectedGenre
    return matchesQuery && matchesGenre
  })

  const finalSongResults = searchQuery.trim().length >= 2 && songResults.length > 0 ? songResults : localFiltered
  const favoriteTracks = useMemo(() => {
    const seen = new Set<string>()
    return favorites.filter((t) => {
      if (!t.id || seen.has(t.id)) return false
      seen.add(t.id)
      return true
    })
  }, [favorites])

  const greeting = useMemo(() => {
    const h = new Date().getHours()
    if (h < 12) return t.goodMorning
    if (h < 19) return t.goodAfternoon
    return t.goodEvening
  }, [t])

  const handleCreatePlaylist = (e: React.FormEvent) => {
    e.preventDefault()
    if (!newPlName.trim()) return
    createPlaylist(newPlName.trim())
    setNewPlName('')
    setNewPlaylistOpen(false)
  }

  const selectedPlaylist = playlists.find((p) => p.id === selectedPlaylistId)

  const withBackground = (children: React.ReactNode) => (
    <div
      ref={rootRef}
      className={`relative h-full w-full overflow-hidden text-white ${
        isFullscreen ? 'fixed inset-0 z-[9999] !h-dvh !w-dvw rounded-none' : ''
      }`}
    >
      <div className="pointer-events-none absolute inset-0">
        <img src="/bg.jpg" alt="" className="size-full object-cover" />
        <div className="absolute inset-0 bg-black/50" />
      </div>
      <div className="relative z-10 flex h-full flex-col">
        {children}
      </div>
    </div>
  )

  if (selectedTrackDetail) {
    return withBackground(
      <TrackDetailView
        track={selectedTrackDetail}
        onBack={() => setSelectedTrackDetail(null)}
        onSelectArtist={(artistName) => {
          setSelectedTrackDetail(null)
          setSelectedArtistName(artistName)
        }}
      />
    )
  }

  if (selectedArtistName) {
    return withBackground(
      <ArtistDetailView
        artistName={selectedArtistName}
        onBack={() => setSelectedArtistName(null)}
        onSelectTrack={(track) => {
          setSelectedArtistName(null)
          setSelectedTrackDetail(track)
        }}
      />
    )
  }

  const sidebarWidgets = (
    <div className="flex h-full min-h-0 flex-col gap-3">
      <GlassPanel variant="strong" className="shrink-0 space-y-0.5 rounded-[24px] p-3">
        <NavButton active={activeTab === 'home'} onClick={() => setActiveTab('home')} icon={Home} label={t.homeTab} />
        <NavButton active={activeTab === 'explore'} onClick={() => setActiveTab('explore')} icon={Search} label={t.exploreTab} />
        <NavButton active={activeTab === 'library'} onClick={() => setActiveTab('library')} icon={Library} label={t.libraryTab} />
      </GlassPanel>

      <GlassPanel variant="strong" className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-[24px] p-3">
        <div className="flex items-center justify-between px-1 mb-2">
          <button
            onClick={() => setShowLibraryPlaylists(!showLibraryPlaylists)}
            className="flex items-center gap-1 text-[11px] font-bold uppercase tracking-wider text-white/40 hover:text-white/70 transition-colors"
          >
            <ChevronDown className={`size-3 transition-transform ${showLibraryPlaylists ? '' : '-rotate-90'}`} />
            {t.yourPlaylists}
          </button>
          <button
            onClick={() => setNewPlaylistOpen(true)}
            className="rounded-xl p-1 text-white/40 hover:bg-white/10 hover:text-white transition-colors"
            title={t.newPlaylist}
          >
            <Plus className="size-3.5" />
          </button>
        </div>
        {showLibraryPlaylists && (
          <div className="flex-1 overflow-y-auto thin-scroll space-y-0.5">
            {playlists.map((pl) => (
              <button
                key={pl.id}
                onClick={() => {
                  setActiveTab('library')
                  setSelectedPlaylistId(pl.id)
                }}
                className="flex w-full items-center gap-2 rounded-xl px-2 py-2 text-left text-[12px] text-white/50 hover:bg-white/5 hover:text-white transition-colors"
              >
                <ListMusic className="size-3.5 shrink-0 text-[#1DB954]/70" />
                <span className="truncate flex-1">{pl.name}</span>
                <span className="text-[10px] text-white/25 shrink-0">{pl.tracks.length}</span>
              </button>
            ))}
            {playlists.length === 0 && (
              <p className="px-2 py-2 text-[11px] text-white/30">{t.noPlaylists}</p>
            )}
          </div>
        )}
      </GlassPanel>
    </div>
  )

  return withBackground(
    <>
      <header className="shrink-0 flex items-center gap-3 px-4 py-3 md:px-6">
          <span className="shrink-0 text-base font-extrabold tracking-tight">CatMusic</span>

          <div className="flex-1 max-w-xl mx-auto">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 size-4 text-white/35 z-10 pointer-events-none" />
              <input
                type="text"
                placeholder={t.searchMusicPlaceholder}
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value)
                  if (e.target.value.trim().length >= 2) setActiveTab('explore')
                }}
                className="cm-glass w-full rounded-full pl-11 pr-10 py-2.5 text-[13px] text-white placeholder:text-white/35 focus:outline-none focus:ring-2 focus:ring-[#1DB954]/40 transition-all"
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full p-1 text-white/40 hover:text-white hover:bg-white/10 transition-colors"
                >
                  <X className="size-3.5" />
                </button>
              )}
            </div>
          </div>

          <div className="hidden md:flex items-center gap-1 shrink-0 relative">
            <button
              onClick={() => setShowNotifications((v) => !v)}
              aria-label="Actividad reciente"
              className={`rounded-full p-2 transition-colors ${
                showNotifications ? 'bg-[#1DB954]/20 text-[#1DB954]' : 'text-white/40 hover:bg-white/10 hover:text-white'
              }`}
            >
              <Bell className="size-4" />
            </button>
            <button
              onClick={() => onOpenSettings?.()}
              aria-label="Abrir ajustes"
              className="rounded-full p-2 text-white/40 hover:bg-white/10 hover:text-white transition-colors"
            >
              <Settings className="size-4" />
            </button>
            <button
              type="button"
              onClick={() => void toggleFullscreen()}
              aria-label={isFullscreen ? 'Salir de pantalla completa' : 'Pantalla completa'}
              aria-pressed={isFullscreen}
              className={`rounded-full p-2 transition-colors ${
                isFullscreen ? 'bg-[#1DB954]/20 text-[#1DB954]' : 'text-white/40 hover:bg-white/10 hover:text-white'
              }`}
            >
              {isFullscreen ? <Minimize2 className="size-4" /> : <Maximize2 className="size-4" />}
            </button>

            {showNotifications && (
              <>
                <div className="fixed inset-0 z-40" onClick={() => setShowNotifications(false)} />
                <GlassPanel variant="strong" className="absolute right-0 top-full z-50 mt-2 w-72 p-3 shadow-2xl">
                  <p className="text-[11px] font-bold uppercase tracking-wider text-white/40 mb-3">Actividad reciente</p>
                  {history.length > 0 ? (
                    <div className="max-h-48 overflow-y-auto thin-scroll space-y-1 mb-3">
                      {history.slice(0, 6).map((entry, idx) => (
                        <button
                          key={`${entry.id}-${idx}`}
                          onClick={() => {
                            playTrack(entry.track, history.map((h) => h.track))
                            setShowNotifications(false)
                          }}
                          className="flex w-full items-center gap-2 rounded-xl px-2 py-2 text-left hover:bg-white/5 transition-colors"
                        >
                          <div className="size-8 shrink-0 overflow-hidden rounded-lg">
                            <img src={entry.track.artworkUrl} alt="" className="size-full object-cover" />
                          </div>
                          <div className="min-w-0 flex-1">
                            <p className="truncate text-[12px] font-semibold">{entry.track.title}</p>
                            <p className="truncate text-[10px] text-white/40">{entry.track.artist}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  ) : (
                    <p className="text-[12px] text-white/40 mb-3">Aún no hay historial de escuchas</p>
                  )}

                  {notifPermission !== 'granted' && notifPermission !== 'unsupported' && (
                    <button
                      onClick={requestNotifications}
                      className="flex w-full items-center justify-center gap-2 rounded-xl bg-white/[0.08] px-3 py-2 text-[12px] font-semibold hover:bg-white/[0.12] transition-colors"
                    >
                      <Bell className="size-3.5" />
                      Activar notificaciones
                    </button>
                  )}
                  {notifPermission === 'denied' && (
                    <p className="mt-2 flex items-center gap-1.5 text-[11px] text-rose-400/80">
                      <BellOff className="size-3.5 shrink-0" />
                      Notificaciones bloqueadas en el navegador
                    </p>
                  )}
                </GlassPanel>
              </>
            )}
          </div>
        </header>

        {/* Body */}
        <div className="flex flex-1 min-h-0 gap-3 px-3 pb-28 md:px-4 md:pb-24">
          {/* Left sidebar - desktop */}
          <aside className="hidden h-full w-[220px] shrink-0 flex-col min-h-0 lg:flex">
            {sidebarWidgets}
          </aside>

          {/* Main scroll area */}
          <main className="flex-1 min-w-0 overflow-y-auto thin-scroll">
            {activeTab === 'home' && (
              <HomeDashboard
                greeting={greeting}
                featuredTrack={featuredTrack}
                favoritesCount={favorites.length}
                playlistsCount={playlists.length}
                historyCount={history.length}
                currentTrack={currentTrack}
                isPlaying={playerState.isPlaying}
                artistBannerUrl={artistBanner}
                onPlayFeatured={() => playTrack(featuredTrack, SEED_TRACKS)}
                onSelectArtist={setSelectedArtistName}
                onSelectTrack={setSelectedTrackDetail}
              />
            )}

            {/* ======= EXPLORE TAB ======= */}
            {activeTab === 'explore' && (
              <div className="space-y-4 pb-4">
                {!searchQuery && (
                  <>
                    <GlassPanel className="p-4 md:p-5">
                      <h3 className="text-sm font-bold text-white/80 mb-3 flex items-center gap-2">
                        <Radio className="size-4 text-[#1DB954]" />
                        Explora por género
                      </h3>
                      <div className="flex flex-wrap items-center gap-2">
                        {GENRES.map((g) => (
                          <button
                            key={g}
                            onClick={() => {
                              setSelectedGenre(g)
                              setSearchQuery(g === 'Todos' ? '' : g)
                            }}
                            className={`rounded-full px-4 py-2 text-[12.5px] font-semibold transition-all ${
                              selectedGenre === g && searchQuery
                                ? 'bg-[#1DB954] text-white shadow-lg shadow-[#1DB954]/25'
                                : 'bg-white/[0.08] text-white/70 hover:bg-white/[0.14] hover:text-white'
                            }`}
                          >
                            {g}
                          </button>
                        ))}
                      </div>
                    </GlassPanel>

                    <GlassPanel className="p-4 md:p-5">
                      <h3 className="text-sm font-bold text-white/80 mb-4 flex items-center gap-2">
                        <Sparkles className="size-4 text-[#1DB954]" />
                        Tendencias
                      </h3>
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                        {SEED_TRACKS.slice(0, 10).map((t) => (
                          <TrackCard key={t.id} track={t} queue={SEED_TRACKS} />
                        ))}
                      </div>
                    </GlassPanel>
                  </>
                )}

                {searchQuery && searchQuery.trim().length >= 2 && (
                  <GlassPanel className="overflow-hidden p-3">
                    <div className="flex items-center gap-1 border-b border-white/[0.06] px-4 pt-3">
                      {(['songs', 'playlists', 'artists'] as SearchTab[]).map((type) => (
                        <button
                          key={type}
                          onClick={() => setSearchTab(type)}
                          className={`px-4 py-2.5 text-[13px] font-semibold rounded-t-xl transition-all ${
                            searchTab === type
                              ? 'text-white border-b-2 border-[#1DB954]'
                              : 'text-white/40 hover:text-white/70'
                          }`}
                        >
                          {type === 'songs' ? 'Canciones' : type === 'playlists' ? 'Playlists' : 'Artistas'}
                        </button>
                      ))}
                    </div>

                    {searchTab === 'songs' && (
                      <div>
                        {isSearching ? (
                          <div className="flex items-center justify-center gap-3 py-16">
                            <span className="size-5 animate-spin rounded-full border-2 border-[#1DB954] border-t-transparent" />
                            <span className="text-sm text-white/50">Buscando canciones...</span>
                          </div>
                        ) : finalSongResults.length > 0 ? (
                          <div className="divide-y divide-white/[0.06]">
                            {finalSongResults.map((t, idx) => (
                              <TrackRow
                                key={`${t.id}-${idx}`}
                                track={t}
                                index={idx + 1}
                                queue={finalSongResults}
                                onSelectArtist={(a) => setSelectedArtistName(a)}
                                onSelectTrack={(tr) => setSelectedTrackDetail(tr)}
                              />
                            ))}
                          </div>
                        ) : (
                          <div className="py-16 text-center">
                            <Music className="mx-auto size-10 text-white/20 mb-3" />
                            <p className="text-sm text-white/40">No se encontraron canciones</p>
                          </div>
                        )}
                      </div>
                    )}

                    {searchTab === 'playlists' && (
                      <div className="p-4">
                        {isSearching ? (
                          <div className="flex items-center justify-center gap-3 py-16">
                            <span className="size-5 animate-spin rounded-full border-2 border-[#1DB954] border-t-transparent" />
                            <span className="text-sm text-white/50">Buscando playlists...</span>
                          </div>
                        ) : playlistResults.length > 0 ? (
                          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                            {playlistResults.map((pl) => (
                              <button
                                key={pl.id}
                                onClick={() =>
