'use client'

import React, { useState, useRef, useEffect } from 'react'
import { Heart, MoreHorizontal, Play, Pause, Info, Radio, ListMusic } from 'lucide-react'
import type { Track } from '@/lib/plugins/cat-music/types'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'
import { formatDuration } from '@/lib/plugins/cat-music/youtube'

export function TrackRow({
  track,
  index,
  queue,
  onSelectArtist,
  onSelectTrack,
  showIndex,
}: {
  track: Track
  index?: number
  queue?: Track[]
  onSelectArtist?: (artistName: string) => void
  onSelectTrack?: (track: Track) => void
  showIndex?: boolean
}) {
  const { currentTrack, playerState, playTrack, togglePlayPause } = useCatMusicPlayer()
  const { isFavorite, toggleFavorite, playlists, addTrackToPlaylist } = useLibrary()
  const [showMenu, setShowMenu] = useState(false)

  const isCurrent = currentTrack?.id === track.id
  const isPlaying = isCurrent && playerState.isPlaying
  const fav = isFavorite(track.id)

  const titleRef = useRef<HTMLButtonElement>(null)
  const artistRef = useRef<HTMLButtonElement>(null)
  const [titleOverflows, setTitleOverflows] = useState(false)
  const [artistOverflows, setArtistOverflows] = useState(false)
  const [titleMarquee, setTitleMarquee] = useState('')
  const [artistMarquee, setArtistMarquee] = useState('')

  useEffect(() => {
    if (titleRef.current) {
      const el = titleRef.current
      const overflow = el.scrollWidth - el.clientWidth
      if (overflow > 0) {
        setTitleOverflows(true)
        setTitleMarquee(`-${overflow}px`)
      } else {
        setTitleOverflows(false)
      }
    }
    if (artistRef.current) {
      const el = artistRef.current
      const overflow = el.scrollWidth - el.clientWidth
      if (overflow > 0) {
        setArtistOverflows(true)
        setArtistMarquee(`-${overflow}px`)
      } else {
        setArtistOverflows(false)
      }
    }
  }, [track.title, track.artist])

  const handlePlayClick = () => {
    if (isCurrent) { togglePlayPause() } else { playTrack(track, queue) }
  }

  return (
    <div
      className={`group relative flex items-center gap-3 px-4 py-2.5 text-[13px] transition-all rounded-lg ${
        isCurrent ? 'bg-[#1DB954]/10' : 'hover:bg-white/[0.04]'
      }`}
    >
      <div className="flex items-center gap-3 min-w-0 flex-1">
        <div className="relative flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-white/[0.04] ring-1 ring-white/[0.06]">
          {showIndex && !isCurrent && (
            <span className="text-[11px] font-semibold text-white/30 tabular-nums">{index}</span>
          )}
          <img
            src={track.artworkUrl}
            alt={track.title}
            className={`size-10 rounded-xl object-cover ${showIndex && !isCurrent ? 'group-hover:opacity-0' : ''}`}
            onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
          />
          <button
            onClick={handlePlayClick}
            aria-label={isPlaying ? 'Pausar' : 'Reproducir'}
            className={`absolute inset-0 flex items-center justify-center bg-black/60 text-white transition-opacity ${
              isCurrent ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'
            }`}
          >
            {isPlaying ? (
              <span className="flex items-end gap-0.5 h-3">
                <span className="w-0.5 bg-[#1DB954] animate-pulse h-3 rounded-full" />
                <span className="w-0.5 bg-[#1DB954] animate-pulse h-2 delay-75 rounded-full" />
                <span className="w-0.5 bg-[#1DB954] animate-pulse h-3.5 delay-150 rounded-full" />
              </span>
            ) : (
              <Play className="size-4 fill-current ml-0.5" />
            )}
          </button>
        </div>

        <div className="min-w-0 flex-1">
          <button
            ref={titleRef}
            onClick={() => onSelectTrack?.(track)}
            className={`block text-left max-w-full font-semibold hover:underline ${titleOverflows ? 'marquee-container' : 'truncate'} ${isCurrent ? 'text-[#1DB954]' : 'text-white'}`}
          >
            <span className={titleOverflows ? 'marquee-text inline-block whitespace-nowrap' : ''} style={titleOverflows ? { ['--marquee-end' as string]: titleMarquee } : undefined}>{track.title}</span>
          </button>
          <button
            ref={artistRef}
            onClick={() => onSelectArtist?.(track.artist)}
            className={`block text-left max-w-full text-[11.5px] text-white/40 hover:text-white/70 hover:underline transition-colors ${artistOverflows ? 'marquee-container' : 'truncate'}`}
          >
            <span className={artistOverflows ? 'marquee-text inline-block whitespace-nowrap' : ''} style={artistOverflows ? { ['--marquee-end' as string]: artistMarquee } : undefined}>{track.artist}</span>
          </button>
        </div>
      </div>

      <span className="text-[11.5px] font-mono text-white/30 shrink-0 w-11 text-right">
        {formatDuration(track.durationSeconds)}
      </span>

      <div className="flex items-center shrink-0">
        <button
          onClick={() => toggleFavorite(track)}
          aria-label={fav ? 'Quitar de favoritos' : 'Añadir a favoritos'}
          className={`rounded-xl p-1.5 transition-all ${
            fav ? 'text-rose-400 opacity-100' : 'text-white/20 opacity-0 group-hover:opacity-100 hover:text-white/60'
          }`}
        >
          <Heart className={`size-4 ${fav ? 'fill-current' : ''}`} />
        </button>

        <div className="relative">
          <button
            onClick={() => setShowMenu((v) => !v)}
            aria-label="Más opciones"
            className="rounded-xl p-1.5 text-white/30 opacity-0 group-hover:opacity-100 hover:bg-white/10 hover:text-white transition-all"
          >
            <MoreHorizontal className="size-4" />
          </button>

          {showMenu && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setShowMenu(false)} />
              <div className="absolute right-0 top-full z-50 mt-1 w-56 cm-glass-strong rounded-2xl p-1.5 shadow-2xl space-y-0.5"
                onClick={(e) => e.stopPropagation()}>
                {onSelectTrack && (
                  <button onClick={() => { onSelectTrack(track); setShowMenu(false) }}
                    className="flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-left text-[12px] text-white/70 hover:bg-white/[0.08] hover:text-white transition-colors">
                    <Info className="size-3.5 text-white/40" />
                    <span>Información de la canción</span>
                  </button>
                )}

                {onSelectArtist && (
                  <button onClick={() => { onSelectArtist(track.artist); setShowMenu(false) }}
                    className="flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-left text-[12px] text-white/70 hover:bg-white/[0.08] hover:text-white transition-colors">
                    <Radio className="size-3.5 text-white/40" />
                    <span>Ver canal del artista</span>
                  </button>
                )}

                <div className="my-1 h-px bg-white/[0.06]" />

                <div className="px-2.5 py-1 text-[10px] font-bold text-white/30 uppercase tracking-wider">
                  Añadir a playlist
                </div>
                {playlists.map((pl) => (
                  <button key={pl.id}
                    onClick={() => { addTrackToPlaylist(pl.id, track); setShowMenu(false) }}
                    className="flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-left text-[12px] text-white/70 hover:bg-white/[0.08] hover:text-white transition-colors">
                    <ListMusic className="size-3.5 text-white/30" />
                    <span className="truncate">{pl.name}</span>
                  </button>
                ))}
                {playlists.length === 0 && (
                  <div className="px-2.5 py-1.5 text-[11px] text-white/20">No tienes playlists</div>
                )}
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import { AnimatePresence, motion } from 'framer-motion'
import { useCallback, useEffect, useState } from 'react'
import useSWR, { mutate as globalMutate } from 'swr'
import { getConversations, getConversationInfo, type ConversationListItem } from '@/app/actions/chat'
import { ChatThread } from '@/components/chat-thread'
import { IconRail } from '@/components/icon-rail'
import { InfoPanel } from '@/components/info-panel'
import { NewChatModal } from '@/components/new-chat-modal'
import { SearchModal } from '@/components/search-modal'
import { SettingsModal } from '@/components/settings-modal'
import { Sidebar } from '@/components/sidebar'
import { UserDock } from '@/components/user-dock'
import { ReleaseNotesModal } from '@/components/release-notes-modal'
import { ChatBackground } from '@/components/chat-background'
import { CallProvider } from '@/components/calls/call-provider'
import { PluginProvider, usePlugins } from '@/lib/plugins/plugin-provider'
import { CatMusicPlayerBar } from '@/components/cat-music/player-bar'
import { themes } from '@/lib/themes'
import { useLanguage } from '@/lib/i18n'

export type AppUser = { id: string; name: string; email: string; image?: string | null; banner?: string | null }
export type Conversation = ConversationListItem

function ChatAppInner({
  user,
  initialConversations,
  onOpenSettings,
}: {
  user: AppUser
  initialConversations: ConversationListItem[]
  onOpenSettings: () => void
}) {
  const [activeView, setActiveView] = useState<string>('chat')
  const [searchOpen, setSearchOpen] = useState(false)
  const [newChatOpen, setNewChatOpen] = useState(false)
  const [infoOpen, setInfoOpen] = useState<boolean>(false)
  const [activeConversationId, setActiveConversationId] = useState<number | null>(
    initialConversations[0]?.id ?? null,
  )

  const { isPluginEnabled, getActiveRailTabs } = usePlugins()
  const { lang } = useLanguage()

  // Restore saved info panel state (collapsed by default on first launch)
  useEffect(() => {
    if (typeof window === 'undefined') return
    const saved = localStorage.getItem('cz-info-panel')
    if (saved === 'open') setInfoOpen(true)
  }, [])

  // Persist info panel preference so it survives app restarts
  useEffect(() => {
    if (typeof window === 'undefined') return
    localStorage.setItem('cz-info-panel', infoOpen ? 'open' : 'closed')
  }, [infoOpen])

  // Restore saved active view after hydration on mount
  useEffect(() => {
    const saved = localStorage.getItem('cz-active-app-view')
    if (saved) {
      setActiveView(saved)
    }
  }, [])

  // Persist active view in localStorage
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('cz-active-app-view', activeView)
    }
  }, [activeView])

  // Fallback to 'chat' if current active plugin view gets disabled
  useEffect(() => {
    if (activeView !== 'chat' && !isPluginEnabled(activeView)) {
      setActiveView('chat')
    }
  }, [activeView, isPluginEnabled])

  // Listen for plugin navigation requests (e.g. Escape from game view via hash)
  useEffect(() => {
    const onHash = () => {
      if (window.location.hash === '#chat') {
        setActiveView('chat')
        history.replaceState(null, '', window.location.pathname + window.location.search)
      }
    }
    window.addEventListener('hashchange', onHash)
    return () => window.removeEventListener('hashchange', onHash)
  }, [])

  const { data: conversations = initialConversations, mutate: mutateConversations } = useSWR(
    'conversations',
    () => getConversations(),
    {
      fallbackData: initialConversations,
      refreshInterval: 3000,
      revalidateOnFocus: true,
      revalidateOnReconnect: true,
    },
  )

  const mutateConversationInfo = useCallback((conversationId: number) => {
    globalMutate(['conversation-info', conversationId])
  }, [])

  const closeSearch = useCallback(() => setSearchOpen(false), [])
  const closeNewChat = useCallback(() => setNewChatOpen(false), [])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault()
        setSearchOpen((v) => !v)
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [])

  const activeConversation =
    conversations.find((c) => c.id === activeConversationId) ?? null

  const activePluginTab = getActiveRailTabs().find((t) => t.id === activeView)
  const PluginViewComponent = activePluginTab?.component

  return (
    <CallProvider user={user}>
      <main className="relative flex h-dvh bg-background pt-7 pb-0 pl-0 pr-0">
        <ChatBackground />
        <IconRail activeView={activeView} onSelectView={setActiveView} />

        {/* WORKSPACE & PLUGINS AREA */}
        <div className="relative flex flex-1 min-w-0 h-full">
          {/* Centered top title text in empty space above workspace/plugins */}
          <div className="absolute -top-6.25 left-0 right-0 flex items-center justify-center text-center pointer-events-none select-none z-20">
            <span className="text-[14px] font-bold text-foreground/80 tracking-wide truncate">
              {activeView === 'chat'
                ? (activeConversation?.title || (lang === 'es' ? 'Chat' : 'Chat'))
                : (activePluginTab?.label || activeView)}
            </span>
          </div>

          {/* VIEW 1: Main CatChat Workspace */}
          {activeView === 'chat' && (
            <div className="flex flex-1 min-w-0 h-full">
              <div className="hidden h-full lg:block ml-3">
                <Sidebar
                  onOpenNewChat={() => setNewChatOpen(true)}
                  conversations={conversations}
                  activeConversationId={activeConversationId}
                  onSelectConversation={setActiveConversationId}
                  onConversationsChange={() => mutateConversations()}
                  currentUserId={user.id}
                />
              </div>
              <ChatThread
                infoOpen={infoOpen}
                onToggleInfo={() => setInfoOpen((v) => !v)}
                user={user}
                conversation={activeConversation}
                onConversationChange={(id) => {
                  setActiveConversationId(id)
                  mutateConversations()
                }}
                onConversationInfoChange={mutateConversationInfo}
              />
              <AnimatePresence initial={false}>
                {infoOpen && activeConversation && (
                  <motion.div
                    key="info-panel"
                    initial={{ width: 0, opacity: 0, x: 32, marginLeft: 0 }}
                    animate={{ width: 288, opacity: 1, x: 0, marginLeft: 12 }}
                    exit={{ width: 0, opacity: 0, x: 32, marginLeft: 0 }}
                    transition={{ type: 'spring', stiffness: 300, damping: 34 }}
                    className="hidden h-full overflow-hidden rounded-3xl lg:block"
                  >
                    <InfoPanel conversation={activeConversation} currentUserId={user.id} />
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          )}

          {/* VIEW 2: Active Plugin View (e.g. CatMusic) */}
          {activeView !== 'chat' && PluginViewComponent && (
            <div
              className={`flex-1 min-w-0 h-full overflow-hidden ml-3 ${
                activeView === 'cat-music'
                  ? 'rounded-3xl'
                  : 'rounded-3xl border border-border/40 bg-card/40 backdrop-blur-xl'
              }`}
            >
              <PluginViewComponent user={user} onOpenSettings={onOpenSettings} />
            </div>
          )}
        </div>

        {/* Persistent YouTube Player Bar for CatMusic (shown ONLY in CatMusic view) */}
        {isPluginEnabled('cat-music') && activeView === 'cat-music' && <CatMusicPlayerBar />}

        <SearchModal
          open={searchOpen}
          onClose={closeSearch}
          onSelectConversation={(id) => {
            setActiveConversationId(id)
            closeSearch()
          }}
          onStartChatWithUser={(id) => {
            setActiveConversationId(id)
            mutateConversations()
            closeSearch()
          }}
        />
        <NewChatModal
          open={newChatOpen}
          onClose={closeNewChat}
          onConversationCreated={(id) => {
            setActiveConversationId(id)
            mutateConversations()
          }}
        />
        <ReleaseNotesModal />
        <UserDock
          onOpenSettings={onOpenSettings}
          user={user}
          activeView={activeView}
          onOpenCatMusic={() => setActiveView('cat-music')}
        />
      </main>
    </CallProvider>
  )
}

export function ChatApp(props: { user: AppUser; initialConversations: ConversationListItem[] }) {
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [theme, setTheme] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('cz-theme')
      if (saved && themes.some((t) => t.id === saved)) return saved
    }
    return 'catchat'
  })

  useEffect(() => {
    const t = themes.find((x) => x.id === theme)
    const root = document.documentElement
    root.setAttribute('data-theme', theme)
    root.classList.toggle('dark', Boolean(t?.dark))
    root.classList.toggle('light', !t?.dark)
    localStorage.setItem('cz-theme', theme)
  }, [theme])

  return (
    <PluginProvider user={props.user}>
      <ChatAppInner {...props} onOpenSettings={() => setSettingsOpen(true)} />
      <SettingsModal
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        theme={theme}
        onThemeChange={setTheme}
        user={props.user}
      />
    </PluginProvider>
  )
}

