    hour: '2-digit',
    minute: '2-digit',
  })
}

function findEvent(
  latestEvents: Record<PolymarketCategory, PolymarketEvent[]>,
  category: PolymarketCategory,
  eventId: string,
): PolymarketEvent | undefined {
  return latestEvents[category].find((e) => e.id === eventId)
}

