  )
}

'use client'

import React, { useRef, useMemo } from 'react'
import { useFrame } from '@react-three/fiber'
import { Text } from '@react-three/drei'
import * as THREE from 'three'
import type { RemotePlayerState } from '@/lib/plugins/tps-controls/multiplayer'

type Props = {
  state: RemotePlayerState
}

export function RemotePlayer({ state }: Props) {
  const groupRef = useRef<THREE.Group>(null)
  const targetPos = useMemo(() => new THREE.Vector3(...state.position), [])
  const currentPos = useRef(new THREE.Vector3(...state.position))
  const targetYaw = useRef(state.rotation)

  React.useEffect(() => {
    targetPos.set(...state.position)
    targetYaw.current = state.rotation
  }, [state.position, state.rotation])

  useFrame(({ camera }, delta) => {
    if (!groupRef.current) return

    currentPos.current.lerp(targetPos, Math.min(1, delta * 15))
    groupRef.current.position.copy(currentPos.current)

    const currentYaw = groupRef.current.rotation.y
    let diff = targetYaw.current - currentYaw
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    groupRef.current.rotation.y += diff * Math.min(1, delta * 15)

    groupRef.current.lookAt(
      camera.position.x,
      groupRef.current.position.y,
      camera.position.z,
    )
  })

  return (
    <group ref={groupRef} position={state.position}>
      <mesh position={[0, 1, 0]} castShadow>
        <capsuleGeometry args={[0.35, 0.8, 8, 16]} />
        <meshStandardMaterial color={state.health > 0 ? '#4488ff' : '#ff4444'} />
      </mesh>

      <mesh position={[0, 0.35, 0]} castShadow>
        <capsuleGeometry args={[0.45, 1.0, 8, 16]} />
        <meshStandardMaterial color={state.health > 0 ? '#3366cc' : '#cc3333'} />
      </mesh>

      <mesh position={[0, 1.8, 0]}>
        <sphereGeometry args={[0.2, 8, 8]} />
        <meshStandardMaterial color={state.health > 0 ? '#ffcc88' : '#ff8888'} />
      </mesh>

      <Text
        position={[0, 2.15, 0]}
        fontSize={0.12}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
      >
        {state.name}
      </Text>
    </group>
  )
}

'use client'

import { motion, AnimatePresence } from 'framer-motion'
import { LogOut, Settings, Download, RotateCw, AlertCircle, Radio, Activity, PhoneOff, Mic, MicOff, Video, VideoOff, MonitorUp, MonitorOff, Sparkles } from 'lucide-react'
import { useRouter } from 'next/navigation'
import { useState, useRef, useEffect, useCallback } from 'react'
import { authClient } from '@/lib/auth-client'
import { useLanguage } from '@/lib/i18n'
import { ElectricBorder } from '@/components/electric-border'
import { useCallContext } from '@/components/calls/call-provider'
import type { ActiveCall } from '@/lib/calls/types'
import { usePlugins } from '@/lib/plugins/plugin-provider'
import { CatMusicDockWidget } from '@/components/cat-music/dock-widget'

function initialsOf(name: string) {
  return name
    .split(' ')
    .map((p) => p[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

type UpdateInfo = {
  version: string
  files: Array<{ url: string; size: number }>
  releaseNotes?: string
}

type DownloadProgress = {
  percent: number
  transferred: number
  total: number
  bytesPerSecond: number
}

type UpdateState =
  | { phase: 'idle' }
  | { phase: 'available'; info: UpdateInfo }
  | { phase: 'downloading'; info: UpdateInfo; progress: DownloadProgress }
  | { phase: 'downloaded'; info: UpdateInfo }
  | { phase: 'error'; message: string }

function getUpdater() {
  if (typeof window === 'undefined') return null
  return (window as any).updater as {
    onAvailable: (cb: (info: UpdateInfo) => void) => () => void
    onDownloadProgress: (cb: (p: DownloadProgress) => void) => () => void
    onDownloaded: (cb: (info: UpdateInfo) => void) => () => void
    onError: (cb: (msg: string) => void) => () => void
    checkForUpdates?: () => Promise<unknown>
    downloadUpdate: () => Promise<void>
    quitAndInstall: () => void
    getVersion?: () => Promise<string>
  } | null
}

function DiscordVoiceDockWidget({ call }: { call: ActiveCall | null }) {
  const { endCall, cancelOutgoingCall, room } = useCallContext()
  const [, forceRender] = useState(0)

  const lastCallRef = useRef(call)
  if (call) {
    lastCallRef.current = call
  }

  const currentCall = call || lastCallRef.current
  const localParticipant = room?.localParticipant

  const micEnabled = localParticipant?.isMicrophoneEnabled ?? false
  const camEnabled = localParticipant?.isCameraEnabled ?? false
  const screenEnabled = localParticipant?.isScreenShareEnabled ?? false

  const refresh = useCallback(() => forceRender((v) => v + 1), [])

  const toggleMic = useCallback(async () => {
    if (!localParticipant) return
    await localParticipant.setMicrophoneEnabled(!micEnabled)
    refresh()
  }, [localParticipant, micEnabled, refresh])

  const toggleCam = useCallback(async () => {
    if (!localParticipant) return
    await localParticipant.setCameraEnabled(!camEnabled)
    refresh()
  }, [localParticipant, camEnabled, refresh])

  const toggleScreenShare = useCallback(async () => {
    if (!localParticipant) return
    if (screenEnabled) {
      await localParticipant.setScreenShareEnabled(false)
    } else {
      try {
        await localParticipant.setScreenShareEnabled(true, {
          resolution: { width: 1920, height: 1080, frameRate: 60 },
          contentHint: 'detail',
        })
      } catch (e) {
        console.error('[DiscordVoiceDockWidget] screen share failed:', e)
      }
    }
    refresh()
  }, [localParticipant, screenEnabled, refresh])

  if (!currentCall) return null

  const peerName = currentCall.peerName || 'Llamada'
  const isRinging = currentCall.state === 'outgoing-ringing'

  return (
    <div className="w-64 border-b border-border/50 bg-[#1e1f22] p-2.5 space-y-2">
      {/* Header section: Connection status & Peer name */}
      <div className="flex items-center justify-between px-0.5">
        <div className="flex items-center gap-2 min-w-0">
          <div className="flex size-8 shrink-0 items-center justify-center rounded-xl bg-[#23a55a]/15 text-[#23a55a]">
            <Radio className="size-4 animate-pulse" />
          </div>
          <div className="min-w-0 flex-1">
            <span className="block text-[12px] font-semibold text-[#23a55a] leading-tight">
              {isRinging ? 'Llamando...' : 'Voz conectada'}
            </span>
            <span className="block truncate text-[11px] font-medium text-white/70 leading-tight">
              {peerName}
            </span>
          </div>
        </div>

        {/* Right side icons: Audio wave + Red hangup button */}
        <div className="flex items-center gap-1.5 shrink-0">
          <Activity className="size-3.5 text-white/40 animate-pulse" />
          <button
            onClick={isRinging ? cancelOutgoingCall : endCall}
            title="Desconectar"
            className="flex size-7 items-center justify-center rounded-lg bg-[#da373c] text-white transition-all hover:bg-[#a12828] active:scale-95 shadow-sm"
          >
            <PhoneOff className="size-3.5" />
          </button>
        </div>
      </div>

      {/* Control Pills Row (Camera, Screen Share, Activities/Grid, Mute) */}
      <div className="grid grid-cols-4 gap-1.5 pt-0.5">
        {/* Cam button */}
        <button
          onClick={toggleCam}
          title={camEnabled ? 'Apagar cámara' : 'Encender cámara'}
          className={`flex h-8 items-center justify-center rounded-lg transition-all ${
            camEnabled
              ? 'bg-white text-[#1e1f22] hover:bg-white/90'
              : 'bg-white/10 text-white/70 hover:bg-white/20 hover:text-white'
          }`}
        >
          {camEnabled ? <Video className="size-4" /> : <VideoOff className="size-4" />}
        </button>

        {/* Screen share button */}
        <button
          onClick={toggleScreenShare}
          title={screenEnabled ? 'Dejar de compartir' : 'Compartir pantalla'}
          className={`flex h-8 items-center justify-center rounded-lg transition-all ${
            screenEnabled
              ? 'bg-white text-[#1e1f22] hover:bg-white/90'
              : 'bg-white/10 text-white/70 hover:bg-white/20 hover:text-white'
          }`}
        >
          {screenEnabled ? <MonitorOff className="size-4" /> : <MonitorUp className="size-4" />}
        </button>

        {/* Activity button */}
        <button
          title="Actividades"
          className="flex h-8 items-center justify-center rounded-lg bg-white/10 text-white/70 transition-all hover:bg-white/20 hover:text-white"
        >
          <Sparkles className="size-4" />
        </button>

        {/* Mic button */}
        <button
          onClick={toggleMic}
          title={micEnabled ? 'Silenciar' : 'Activar micrófono'}
          className={`flex h-8 items-center justify-center rounded-lg transition-all ${
            micEnabled
              ? 'bg-white/10 text-white/70 hover:bg-white/20 hover:text-white'
              : 'bg-[#da373c] text-white hover:bg-[#da373c]/90'
          }`}
        >
          {micEnabled ? <Mic className="size-4" /> : <MicOff className="size-4" />}
        </button>
      </div>
    </div>
  )
}

export function UserDock({
  onOpenSettings,
  user,
  activeView,
  onOpenCatMusic,
}: {
  onOpenSettings: () => void
  user: { id: string; name: string; email: string; image?: string | null; banner?: string | null }
  activeView?: string
  onOpenCatMusic?: () => void
}) {
  const { t, lang } = useLanguage()
  const { isPluginEnabled, pluginUpdates, updatePlugin, dismissPluginUpdate, installingPluginId, installProgressMap } = usePlugins()
  const router = useRouter()
  const [signingOut, setSigningOut] = useState(false)
  const [showMenu, setShowMenu] = useState(false)
  const dockRef = useRef<HTMLDivElement>(null)
  const downloadingRef = useRef(false)
  const updateSeenRef = useRef(false)
  const pluginUpdateSeenRef = useRef(false)

  const [update, setUpdate] = useState<UpdateState>({ phase: 'idle' })
  const [appVersion, setAppVersion] = useState<string | null>(
    process.env.NEXT_PUBLIC_APP_VERSION ?? null
  )

  useEffect(() => {
    const updater = getUpdater()
    if (updater?.getVersion) {
      updater.getVersion().then((v: string) => setAppVersion(v)).catch(() => {})
    }
  }, [])

  useEffect(() => {
    const updater = getUpdater()
    if (!updater) return
    const check = () => {
      if (downloadingRef.current) return
      updater.checkForUpdates?.().catch(() => {})
    }
    const id = setInterval(check, 10_000)
    check()
    return () => clearInterval(id)
  }, [])

  useEffect(() => {
    const updater = getUpdater()
    if (!updater) return

    const unsubAvailable = updater.onAvailable((info) => {
      if (updateSeenRef.current) return
      updateSeenRef.current = true
      setUpdate({ phase: 'available', info })
    })
    const unsubProgress = updater.onDownloadProgress((progress) => {
      setUpdate((prev) => {
        if (prev.phase === 'downloading' || prev.phase === 'available') {
          const info = prev.phase === 'downloading' ? prev.info : (prev as any).info
          return { phase: 'downloading' as const, info, progress }
        }
        return prev
      })
    })
    const unsubDownloaded = updater.onDownloaded((info) => setUpdate({ phase: 'downloaded', info }))
    const unsubError = updater.onError((msg) => setUpdate({ phase: 'error', message: msg }))

    return () => {
      unsubAvailable(); unsubProgress(); unsubDownloaded(); unsubError()
    }
  }, [])

  useEffect(() => {
    if (update.phase !== 'idle') setShowMenu(true)
  }, [update.phase])

  const handleInstall = useCallback(async () => {
    const updater = getUpdater()
    if (!updater || update.phase !== 'available') return
    downloadingRef.current = true
    setUpdate((prev) =>
      prev.phase === 'available'
        ? { phase: 'downloading', info: prev.info, progress: { percent: 0, transferred: 0, total: 0, bytesPerSecond: 0 } }
        : prev
    )
    try {
      await updater.downloadUpdate()
    } catch {
      setUpdate((prev) => (prev.phase === 'downloading' ? { phase: 'error', message: 'Download failed' } : prev))
    } finally {
      downloadingRef.current = false
    }
  }, [update.phase])

  const handleRestart = useCallback(() => {
    getUpdater()?.quitAndInstall()
  }, [])

  const handleDismiss = useCallback(() => {
    setShowMenu(false)
    updateSeenRef.current = false
    setTimeout(() => setUpdate({ phase: 'idle' }), 300)
  }, [])

  const handleSignOut = async () => {
    if (signingOut) return
    setSigningOut(true)
    await authClient.signOut()
    router.push('/sign-in')
    router.refresh()
  }

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dockRef.current && !dockRef.current.contains(event.target as Node)) {
        setShowMenu(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  const activePluginUpdateId = Object.keys(pluginUpdates || {})[0]
  const activePluginUpdate = activePluginUpdateId ? pluginUpdates[activePluginUpdateId] : null
  const hasPluginUpdate = Boolean(activePluginUpdate)
  const isPluginUpdating = Boolean(activePluginUpdateId && installingPluginId === activePluginUpdateId)
  const pluginUpdateProgress = activePluginUpdateId ? (installProgressMap[activePluginUpdateId] || 0) : 0

  const { activeCall } = useCallContext()
  const hasActiveCall = Boolean(activeCall)
  const hasUpdate = update.phase !== 'idle'
  const glowActive = showMenu || hasUpdate || hasPluginUpdate || hasActiveCall

  useEffect(() => {
    if (hasPluginUpdate && !pluginUpdateSeenRef.current) {
      pluginUpdateSeenRef.current = true
      setShowMenu(true)
    }
    if (!hasPluginUpdate) {
      pluginUpdateSeenRef.current = false
    }
  }, [hasPluginUpdate])

  const wasPlayingBeforeCallRef = useRef(false)

  // Pause music on voice/video call start and resume on call end
  useEffect(() => {
    if (!isPluginEnabled('cat-music') || typeof window === 'undefined') return

    if (hasActiveCall) {
      window.dispatchEvent(new CustomEvent('cat-music:pause-call'))
    } else {
      window.dispatchEvent(new CustomEvent('cat-music:resume-call'))
    }
  }, [hasActiveCall, isPluginEnabled])

  function handleToggle() {
    // If there's an update and menu is closed, show update panel
    // If there's an update and menu is open, toggle off
    // If no update, toggle profile panel
    if ((hasUpdate || hasPluginUpdate) && !showMenu) {
      setShowMenu(true)
    } else {
      setShowMenu((v) => !v)
    }
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 24, scale: 0.95 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ type: 'spring', stiffness: 380, damping: 32, delay: 0.15 }}
      className="fixed bottom-4 left-4 z-50 w-64"
    >
      <ElectricBorder active={glowActive} roundedClass="rounded-2xl" className="w-64">
        <div
          ref={dockRef}
          className="relative z-10 flex w-64 flex-col-reverse rounded-2xl border border-white/10 shadow-lg backdrop-blur-sm overflow-hidden"
        >
          {/* Collapsed bar */}
          <div
            className="flex w-full cursor-pointer items-center justify-between gap-2 py-2 pl-2 pr-2.5"
            onClick={handleToggle}
          >
            <div className="flex items-center gap-2.5 rounded-xl px-1 py-0.5 min-w-0 flex-1">
              <span className="relative flex size-9 shrink-0 items-center justify-center rounded-full bg-secondary text-[12px] font-semibold text-muted-foreground">
                {user.image ? (
                  <img
                    src={user.image || '/placeholder.svg'}
                    alt={user.name}
                    className="size-9 rounded-full object-cover"
                  />
                ) : (
                  initialsOf(user.name)
                )}
                <span className={`absolute -bottom-0.5 -right-0.5 size-3 rounded-full border-2 border-card ${hasUpdate ? 'bg-[#5865F2] animate-pulse' : 'bg-success'}`} />
              </span>
              <span className="min-w-0 flex-1 pr-1">
                <span className="block truncate text-[13px] font-semibold leading-tight">
                  {user.name}
                  {appVersion && (
                    <span className="ml-1.5 inline-flex items-center rounded-full bg-secondary/60 px-1.5 py-px text-[9.5px] font-medium text-muted-foreground">v{appVersion}</span>
                  )}
                </span>
                <span className="block truncate text-[11px] leading-tight text-muted-foreground">
                  {user.email}
                </span>
              </span>
            </div>
            <div className="flex items-center gap-0.5 shrink-0">
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  onOpenSettings()
                }}
                aria-label={t.settingsLabel}
                className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground"
              >
                <Settings className="size-4" />
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  handleSignOut()
                }}
                aria-label={t.signOutLabel}
                disabled={signingOut}
                className="rounded-lg p-1.5 text-muted-foreground transition-colors hover:bg-secondary hover:text-foreground disabled:opacity-50"
              >
                <LogOut className="size-4" />
              </button>
            </div>
          </div>

          {/* CatMusic Dock Mini Player (shown in Chat view when profile menu & calls are inactive) */}
          <AnimatePresence mode="wait">
            {isPluginEnabled('cat-music') && activeView !== 'cat-music' && !showMenu && !hasActiveCall && (
              <motion.div
                key="cat-music-dock-widget"
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                className="overflow-hidden"
              >
                <CatMusicDockWidget onOpenCatMusic={onOpenCatMusic} />
              </motion.div>
            )}
          </AnimatePresence>

          {/* Discord Voice Call Dock Widget */}
          <AnimatePresence>
            {hasActiveCall && (
              <motion.div
                key="voice-dock"
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                className="overflow-hidden"
              >
                <DiscordVoiceDockWidget call={activeCall} />
              </motion.div>
            )}
          </AnimatePresence>

          {/* Expanded panel */}
          <AnimatePresence mode="wait">
            {showMenu && (
              <motion.div
                key="expanded"
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.3, ease: [0.16, 1, 0.3, 1] }}
                className="overflow-hidden"
              >
                {hasUpdate ? (
                  /* Update panel */
                  <div className="w-64">
                    <div className="flex items-center justify-between px-3.5 py-2.5 border-b border-border/60 bg-linear-to-r from-[#5865F2]/10 via-transparent to-transparent">
                      <div className="flex items-center gap-2">
                        <Download className="size-4 text-[#5865F2]" />
                        <span className="text-[12px] font-semibold text-foreground">
                          {update.phase === 'available' && 'Update Available'}
                          {update.phase === 'downloading' && 'Downloading...'}
                          {update.phase === 'downloaded' && 'Ready to Install'}
                          {update.phase === 'error' && 'Update Error'}
                        </span>
                      </div>
                      <button
                        onClick={(e) => { e.stopPropagation(); handleDismiss() }}
                        className="text-muted-foreground hover:text-foreground transition-colors p-0.5 rounded-full hover:bg-secondary/60"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="size-3.5"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
                      </button>
                    </div>

                    <div className="px-3.5 py-3">
                      {update.phase === 'available' && (
                        <div className="space-y-3">
                          <div className="space-y-1">
                            <span className="text-[12px] text-muted-foreground">Version {update.info.version}</span>
                            {update.info.files?.[0]?.size != null && (
                              <span className="block text-[11px] text-muted-foreground/70">{formatSize(update.info.files[0].size)}</span>
                            )}
                            {update.info.releaseNotes && (
                              <p className="text-[11px] text-muted-foreground/80 mt-1.5 leading-relaxed max-h-16 overflow-y-auto thin-scroll">
                                {update.info.releaseNotes.replace(/<[^>]*>/g, '').trim()}
                              </p>
                            )}
                          </div>
                          <button
                            onClick={(e) => { e.stopPropagation(); handleInstall() }}
                            className="w-full flex items-center justify-center gap-2 rounded-lg bg-[#5865F2] px-4 py-2 text-[12.5px] font-semibold text-white hover:bg-[#5865F2]/90 transition-all active:scale-[0.98] shadow-lg shadow-[#5865F2]/25"
                          >
                            <Download className="size-3.5" /> Install
                          </button>
                        </div>
                      )}

                      {update.phase === 'downloading' && (
                        <div className="space-y-2.5">
                          <div className="flex items-center justify-between text-[11px] text-muted-foreground">
                            <span>Downloading update...</span>
                            <span>{Math.round(update.progress.percent)}%</span>
                          </div>
                          <div className="h-2 rounded-full bg-secondary overflow-hidden">
                            <motion.div
                              className="h-full rounded-full bg-[#5865F2]"
                              initial={{ width: 0 }}
                              animate={{ width: `${Math.round(update.progress.percent)}%` }}
                              transition={{ duration: 0.3, ease: 'easeOut' }}
                            />
                          </div>
                          {update.progress.bytesPerSecond > 0 && (
                            <span className="text-[10px] text-muted-foreground/60">{formatSize(update.progress.bytesPerSecond)}/s</span>
                          )}
                        </div>
                      )}

                      {update.phase === 'downloaded' && (
                        <div className="space-y-3">
                          <span className="text-[12px] text-muted-foreground">Update downloaded. Restart to apply.</span>
                          <button
                            onClick={(e) => { e.stopPropagation(); handleRestart() }}
                            className="w-full flex items-center justify-center gap-2 rounded-lg bg-[#5865F2] px-4 py-2 text-[12.5px] font-semibold text-white hover:bg-[#5865F2]/90 transition-all active:scale-[0.98] shadow-lg shadow-[#5865F2]/25"
                          >
                            <RotateCw className="size-3.5" /> Restart Now
                          </button>
                        </div>
                      )}

                      {update.phase === 'error' && (
                        <div className="space-y-3">
                          <div className="flex items-start gap-2">
                            <AlertCircle className="size-4 text-red-400 shrink-0 mt-0.5" />
                            <span className="text-[12px] text-muted-foreground">{update.message}</span>
                          </div>
                          <button
                            onClick={(e) => { e.stopPropagation(); setUpdate({ phase: 'idle' }) }}
                            className="w-full flex items-center justify-center gap-2 rounded-lg bg-secondary px-4 py-2 text-[12.5px] font-semibold text-foreground hover:bg-secondary/80 transition-all"
                          >
                            Dismiss
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                ) : hasPluginUpdate && activePluginUpdate ? (
                  /* Plugin Update panel (same spot as CatChat app update) */
                  <div className="w-64">
                    <div className="flex items-center justify-between px-3.5 py-2.5 border-b border-border/60 bg-linear-to-r from-emerald-500/10 via-transparent to-transparent">
                      <div className="flex items-center gap-2">
                        <Download className="size-4 text-emerald-400 animate-pulse" />
                        <span className="text-[12px] font-semibold text-foreground">
                          {lang === 'es' ? 'Actualización de Plugin' : 'Plugin Update Available'}
                        </span>
                      </div>
                      <button
                        onClick={(e) => { e.stopPropagation(); activePluginUpdateId && dismissPluginUpdate(activePluginUpdateId) }}
                        className="text-muted-foreground hover:text-foreground transition-colors p-0.5 rounded-full hover:bg-secondary/60"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="size-3.5"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
                      </button>
                    </div>

                    <div className="px-3.5 py-3 space-y-3">
                      <div className="space-y-1">
                        <div className="flex items-center justify-between">
                          <span className="text-[12.5px] font-bold text-foreground">{activePluginUpdate.name}</span>
                          <span className="font-mono text-[10px] font-bold text-emerald-400 bg-emerald-500/15 border border-emerald-500/30 px-1.5 py-0.5 rounded">{activePluginUpdate.newVersion}</span>
                        </div>
                        {activePluginUpdate.releaseNotes && (
                          <p className="text-[11px] text-muted-foreground/80 mt-1.5 leading-relaxed max-h-16 overflow-y-auto thin-scroll">
                            {activePluginUpdate.releaseNotes.replace(/<[^>]*>/g, '').trim()}
                          </p>
                        )}
                      </div>
                      {isPluginUpdating ? (
                        <div className="space-y-2.5">
                          <div className="flex items-center justify-between text-[11px] text-muted-foreground">
                            <span>{lang === 'es' ? 'Descargando actualización…' : 'Downloading update…'}</span>
                            <span>{pluginUpdateProgress}%</span>
                          </div>
                          <div className="h-2 rounded-full bg-secondary overflow-hidden">
                            <motion.div
                              className="h-full rounded-full bg-emerald-500"
                              initial={{ width: 0 }}
                              animate={{ width: `${pluginUpdateProgress}%` }}
                              transition={{ duration: 0.3, ease: 'easeOut' }}
                            />
                          </div>
                        </div>
                      ) : (
                        <button
                          onClick={(e) => { e.stopPropagation(); activePluginUpdateId && updatePlugin(activePluginUpdateId) }}
                          className="w-full flex items-center justify-center gap-2 rounded-lg bg-emerald-600 px-4 py-2 text-[12.5px] font-semibold text-white hover:bg-emerald-500 transition-all active:scale-[0.98] shadow-lg shadow-emerald-600/25"
                        >
                          <Download className="size-3.5" /> {lang === 'es' ? 'Actualizar Plugin' : 'Update Plugin'}
                        </button>
                      )}
                    </div>
                  </div>
                ) : (
                  /* Profile panel */
                  <div
                    className="relative flex flex-col items-center px-4 pb-4 pt-10 rounded-t-2xl overflow-hidden"
                    style={user.banner ? { backgroundImage: `url(${user.banner})`, backgroundSize: 'cover', backgroundPosition: 'center' } : undefined}
                  >
                    {user.banner && <div className="absolute inset-0 bg-linear-to-b from-black/40 to-black/70" />}
                    <span className="relative mb-3 flex size-16 shrink-0 items-center justify-center rounded-full bg-secondary text-xl font-semibold text-muted-foreground ring-2 ring-white/20">
                      {user.image ? (
                        <img src={user.image || '/placeholder.svg'} alt={user.name} className="size-16 rounded-full object-cover" />
                      ) : (
                        initialsOf(user.name)
                      )}
                      <span className="absolute bottom-0.5 right-0.5 size-4 rounded-full border-[3px] border-card bg-success" />
                    </span>
                    <span className={`relative max-w-full truncate text-center text-base font-semibold leading-tight ${user.banner ? 'text-white' : ''}`}>
                      {user.name}
                    </span>
                    <span className={`relative mt-0.5 max-w-full truncate text-center text-xs leading-tight ${user.banner ? 'text-white/80' : 'text-muted-foreground'}`}>
                      {user.email}
                    </span>
                  </div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </ElectricBorder>
    </motion.div>
  )
}

'use client'

import { AnimatePresence, motion } from 'framer-motion'
import { MessageSquare, UserPlus, MoreHorizontal, X, Smile } from 'lucide-react'
import { useCallback, useEffect, useRef, useState } from 'react'

/* ─── Types ─────────────────────────────────────── */

export interface PopoverUser {
  id: string
  name: string
  image?: string | null
  banner?: string | null
  email?: string
  createdAt?: string | null
  isOnline?: boolean
}

interface Props {
  user: PopoverUser
  currentUserId: string
  anchorRect: DOMRect | null
  onClose: () => void
  onOpenFullProfile: () => void
  onSendMessage?: (content: string) => void
}

/* ─── Helpers ───────────────────────────────────── */

function initialsOf(name: string) {
  return name
    .split(' ')
    .map((p) => p[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

function getPopoverPosition(anchor: DOMRect) {
  const W = 300
  const H = 276
  const GAP = 8
  let x = anchor.right + GAP
  let y = anchor.top

  // flip left if overflows right
  if (x + W > window.innerWidth - 16) {
    x = anchor.left - W - GAP
  }
  // clamp to left edge
  if (x < 16) x = 16

  // clamp bottom
  if (y + H > window.innerHeight - 16) {
    y = window.innerHeight - H - 16
  }
  // clamp top
  if (y < 16) y = 16

  return { x, y }
}

/* ─── Component ─────────────────────────────────── */

export function UserPopover({
  user,
  currentUserId,
  anchorRect,
  onClose,
  onOpenFullProfile,
  onSendMessage,
}: Props) {
  const ref = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const [quickMsg, setQuickMsg] = useState('')

  const isSelf = user.id === currentUserId

  // Close on click outside
  useEffect(() => {
    function handler(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        onClose()
      }
    }
    function keyHandler(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('mousedown', handler)
    document.addEventListener('keydown', keyHandler)
    return () => {
      document.removeEventListener('mousedown', handler)
      document.removeEventListener('keydown', keyHandler)
    }
  }, [onClose])

  const handleSendQuickMsg = useCallback(() => {
    if (!quickMsg.trim()) return
    onSendMessage?.(quickMsg.trim())
    setQuickMsg('')
  }, [quickMsg, onSendMessage])

  if (!anchorRect) return null

  const pos = getPopoverPosition(anchorRect)

  // Banner color fallback — use a hash of the user's name for a deterministic color
  const bannerColor = user.banner
    ? undefined
    : `hsl(${[...user.name].reduce((a, c) => a + c.charCodeAt(0), 0) % 360}, 55%, 48%)`

  return (
    <AnimatePresence>
      <motion.div
        ref={ref}
        initial={{ opacity: 0, scale: 0.92, y: 8 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.92, y: 8 }}
        transition={{ duration: 0.18, ease: 'easeOut' }}
        className="fixed z-[60] w-[300px] h-[276px] overflow-hidden rounded-2xl border border-border bg-popover shadow-2xl flex flex-col justify-between"
        style={{ left: pos.x, top: pos.y }}
      >
        {/* Banner */}
        <div
          className="relative h-[105px] w-full shrink-0 overflow-hidden"
          style={!user.banner ? { backgroundColor: bannerColor } : undefined}
        >
          {user.banner && (
            <img src={user.banner} alt="" className="absolute inset-0 size-full object-cover" />
          )}
          {/* Action buttons on banner */}
          {!isSelf && (
            <div className="absolute right-2 top-2 flex gap-1.5">
              <button
                className="flex size-8 items-center justify-center rounded-full bg-black/40 text-white/80 backdrop-blur-sm transition-colors hover:bg-black/60 hover:text-white"
                title="Add friend"
              >
                <UserPlus className="size-4" />
              </button>
              <button
                className="flex size-8 items-center justify-center rounded-full bg-black/40 text-white/80 backdrop-blur-sm transition-colors hover:bg-black/60 hover:text-white"
                title="More options"
              >
                <MoreHorizontal className="size-4" />
              </button>
            </div>
          )}
        </div>

        {/* Avatar (overlapping banner) */}
        <div className="relative px-4">
          <div className="relative inline-block -mt-11">
            <button
              onClick={onOpenFullProfile}
              className="flex size-[80px] items-center justify-center overflow-hidden rounded-full border-[6px] border-popover bg-secondary transition-transform hover:scale-105 shadow-md"
              title="View full profile"
            >
              {user.image ? (
                <img src={user.image} alt={user.name} className="size-full object-cover" />
              ) : (
                <span className="text-2xl font-bold text-muted-foreground">
                  {initialsOf(user.name)}
                </span>
              )}
            </button>

            {/* Presence indicator badge matching screenshot */}
            <div
              className="absolute bottom-0 right-0 flex size-6 items-center justify-center rounded-full border-[4px] border-popover bg-popover shadow-sm"
              title={user.isOnline ? 'Conectado' : 'Desconectado'}
            >
              {user.isOnline ? (
                <span className="size-3.5 rounded-full bg-[#23a55a]" />
              ) : (
                <span className="flex size-3.5 items-center justify-center rounded-full bg-[#80848e]">
                  <span className="size-1.5 rounded-full bg-popover" />
                </span>
              )}
            </div>
          </div>
        </div>

        {/* Name + username */}
        <div className="px-4 pt-2 pb-3">
          <h3 className="text-[17px] font-bold text-foreground leading-tight">{user.name}</h3>
          <p className="text-sm text-muted-foreground">@{user.name.toLowerCase().replace(/\s+/g, '')}</p>
        </div>

        {/* Quick message */}
        {!isSelf && (
          <div className="border-t border-border px-3 py-3">
            <div className="flex items-center gap-2 rounded-lg border border-border bg-secondary/50 px-3 py-2">
              <input
                ref={inputRef}
                type="text"
                placeholder={`Message @${user.name}`}
                value={quickMsg}
                onChange={(e) => setQuickMsg(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleSendQuickMsg()
                }}
                className="min-w-0 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground/60"
              />
              <button className="shrink-0 text-muted-foreground hover:text-foreground transition-colors">
                <Smile className="size-4" />
              </button>
            </div>
          </div>
        )}

        {/* Self: Edit profile link */}
        {isSelf && (
          <div className="border-t border-border px-4 py-3">
            <button
              onClick={onOpenFullProfile}
              className="w-full rounded-lg bg-primary px-3 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:opacity-90"
            >
              Edit Profile
            </button>
          </div>
        )}
      </motion.div>
    </AnimatePresence>
  )
}

'use client'

import { AnimatePresence, motion } from 'framer-motion'
import { MessageSquare, UserPlus, MoreHorizontal, X } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import type { PopoverUser } from './user-popover'

/* ─── Helpers ───────────────────────────────────── */

function initialsOf(name: string) {
  return name
    .split(' ')
    .map((p) => p[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

function formatDate(dateStr: string | null | undefined): string {
  if (!dateStr) return '—'
  const d = new Date(dateStr)
  return d.toLocaleDateString('es', { day: 'numeric', month: 'short', year: 'numeric' })
}

/* ─── Note persistence (localStorage) ──────────── */

function getNoteKey(currentUserId: string, targetUserId: string) {
  return `cz-note:${currentUserId}:${targetUserId}`
}

function loadNote(currentUserId: string, targetUserId: string): string {
  if (typeof window === 'undefined') return ''
  return localStorage.getItem(getNoteKey(currentUserId, targetUserId)) || ''
}

function saveNote(currentUserId: string, targetUserId: string, note: string) {
  if (typeof window === 'undefined') return
  localStorage.setItem(getNoteKey(currentUserId, targetUserId), note)
}

/* ─── Tabs ──────────────────────────────────────── */

type Tab = 'activity' | 'mutual-friends' | 'mutual-servers'

/* ─── Component ─────────────────────────────────── */

export function UserProfileModal({
  user,
  currentUserId,
  onClose,
}: {
  user: PopoverUser
  currentUserId: string
  onClose: () => void
}) {
  const [activeTab, setActiveTab] = useState<Tab>('activity')
  const [note, setNote] = useState(() => loadNote(currentUserId, user.id))
  const noteTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const isSelf = user.id === currentUserId

  // Close on Escape
  useEffect(() => {
    function handler(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [onClose])

  // Debounced note save
  function handleNoteChange(val: string) {
    setNote(val)
    if (noteTimeoutRef.current) clearTimeout(noteTimeoutRef.current)
    noteTimeoutRef.current = setTimeout(() => {
      saveNote(currentUserId, user.id, val)
    }, 500)
  }

  // Banner color fallback
  const bannerColor = user.banner
    ? undefined
    : `hsl(${[...user.name].reduce((a, c) => a + c.charCodeAt(0), 0) % 360}, 55%, 48%)`

  const tabs: { id: Tab; label: string }[] = [
    { id: 'activity', label: 'Activity' },
    { id: 'mutual-friends', label: 'No mutual friends' },
    { id: 'mutual-servers', label: 'No mutual servers' },
  ]

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[70] flex items-center justify-center">
        {/* Overlay */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={onClose}
          className="absolute inset-0 bg-black/60 backdrop-blur-[2px]"
        />

        {/* Modal */}
        <motion.div
          initial={{ opacity: 0, scale: 0.9, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, y: 20 }}
          transition={{ type: 'spring', stiffness: 350, damping: 32 }}
          className="relative flex w-full max-w-[880px] max-h-[85vh] overflow-hidden rounded-2xl border border-border bg-card shadow-2xl"
        >
          {/* Close button */}
          <button
            onClick={onClose}
            className="absolute right-3 top-3 z-20 flex size-8 items-center justify-center rounded-full bg-black/40 text-white/80 backdrop-blur-sm transition-colors hover:bg-black/60 hover:text-white"
          >
            <X className="size-4" />
          </button>

          {/* ── Left column: Identity ─────── */}
          <div className="flex w-[340px] shrink-0 flex-col border-r border-border">
            {/* Banner */}
            <div
              className="relative h-[120px] w-full shrink-0 overflow-hidden"
              style={!user.banner ? { backgroundColor: bannerColor } : undefined}
            >
              {user.banner && (
                <img src={user.banner} alt="" className="absolute inset-0 size-full object-cover" />
              )}
            </div>

            {/* Avatar overlapping banner */}
            <div className="relative px-5">
              <div className="-mt-12 flex size-[88px] items-center justify-center overflow-hidden rounded-full border-[5px] border-card bg-secondary">
                {user.image ? (
                  <img src={user.image} alt={user.name} className="size-full object-cover" />
                ) : (
                  <span className="text-3xl font-bold text-muted-foreground">
                    {initialsOf(user.name)}
                  </span>
                )}
              </div>
              {/* Presence dot */}
              <div className="absolute bottom-0 left-[76px] size-5 rounded-full border-[3px] border-card bg-green-500" />
            </div>

            {/* Name + username */}
            <div className="px-5 pt-2.5">
              <h2 className="text-xl font-bold text-foreground leading-tight">{user.name}</h2>
              <p className="text-sm text-muted-foreground">@{user.name.toLowerCase().replace(/\s+/g, '')}</p>
            </div>

            {/* Action buttons */}
            <div className="flex items-center gap-2 px-5 pt-4">
              {!isSelf ? (
                <>
                  <button className="flex items-center gap-1.5 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:opacity-90">
                    <MessageSquare className="size-4" />
                    Message
                  </button>
                  <button
                    className="flex size-9 items-center justify-center rounded-lg bg-secondary text-muted-foreground transition-colors hover:bg-secondary/80 hover:text-foreground"
                    title="Add friend"
                  >
                    <UserPlus className="size-4" />
                  </button>
                  <button
                    className="flex size-9 items-center justify-center rounded-lg bg-secondary text-muted-foreground transition-colors hover:bg-secondary/80 hover:text-foreground"
                    title="More options"
                  >
                    <MoreHorizontal className="size-4" />
                  </button>
                </>
              ) : (
                <button className="w-full rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground transition-colors hover:opacity-90">
                  Edit Profile
                </button>
              )}
            </div>

            {/* Metadata */}
            <div className="mt-4 border-t border-border px-5 py-3 space-y-2.5">
              <div>
                <p className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Member since</p>
                <p className="text-sm text-foreground">{formatDate(user.createdAt)}</p>
              </div>
            </div>

            {/* Private note */}
            {!isSelf && (
              <div className="border-t border-border px-5 py-3 mt-auto">
                <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
                  Note (only visible to you)
                </p>
                <textarea
                  value={note}
                  onChange={(e) => handleNoteChange(e.target.value)}
                  placeholder="Click to add a note"
                  className="thin-scroll w-full resize-none rounded-md border-none bg-transparent p-0 text-sm text-foreground/70 outline-none placeholder:text-muted-foreground/40 placeholder:italic focus:text-foreground"
                  rows={2}
                />
              </div>
            )}
          </div>

          {/* ── Right column: Tabs ────────── */}
          <div className="flex min-w-0 flex-1 flex-col">
            {/* Tab bar */}
            <div className="flex gap-4 border-b border-border px-5 pt-4">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`pb-3 text-sm font-semibold transition-colors ${
                    activeTab === tab.id
                      ? 'border-b-2 border-foreground text-foreground'
                      : 'text-muted-foreground hover:text-foreground'
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Tab content */}
            <div className="thin-scroll flex-1 overflow-y-auto p-5">
              {activeTab === 'activity' && (
                <div className="flex h-full flex-col items-center justify-center text-center py-12">
                  <p className="text-base font-semibold text-foreground">
                    {user.name} doesn&apos;t have any activity to share here
                  </p>
                  <p className="mt-1.5 text-sm text-muted-foreground">
                    What a mystery! Ask them to tell you a secret
                  </p>
                  {!isSelf && (
                    <button className="mt-5 flex items-center gap-1.5 rounded-lg bg-secondary px-4 py-2 text-sm font-semibold text-foreground transition-colors hover:bg-secondary/80">
                      <MessageSquare className="size-4" />
                      Message
                    </button>
                  )}
                </div>
              )}

              {activeTab === 'mutual-friends' && (
                <div className="flex h-full flex-col items-center justify-center text-center py-12">
                  <p className="text-sm text-muted-foreground">No mutual friends</p>
                </div>
              )}

              {activeTab === 'mutual-servers' && (
                <div className="flex h-full flex-col items-center justify-center text-center py-12">
                  <p className="text-sm text-muted-foreground">No mutual servers</p>
                </div>
              )}
            </div>
          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  )
}

const { app, BrowserWindow, ipcMain, desktopCapturer, session } = require('electron')
const path = require('path')
const fs = require('fs')
const http = require('http')
const { autoUpdater } = require('electron-updater')
const { registerCommandRunnerIPC } = require('./electron/commandRunner')
const { registerPluginInstallerIPC } = require('./electron/pluginInstaller')

process.on('uncaughtException', (error) => {
  console.error('[Main] Uncaught Exception:', error)
})

process.on('unhandledRejection', (reason) => {
  console.error('[Main] Unhandled Rejection:', reason)
})

// Use overlay scrollbars on Windows/Linux (no native arrow buttons)
if (process.platform === 'win32') {
  app.commandLine.appendSwitch('enable-features', 'OverlayScrollbar,FluentOverlayScrollbar')
  app.commandLine.appendSwitch('disable-features', 'FluentScrollbar')
} else {
  app.commandLine.appendSwitch('enable-features', 'OverlayScrollbar,FluentOverlayScrollbar')
}


// This helps the embedded Next server find `DATABASE_URL` and other runtime vars.
try {
