  const n = new Notification(`Nueva apuesta — ${CATEGORY_LABELS[alert.category]}`, {
    body: alert.title,
    icon: alert.image || '/catchat.png',
    tag: alert.id,
  })

  n.onclick = () => {
    window.open(`${POLYMARKET_EVENT_URL}/${alert.slug}`, '_blank', 'noopener,noreferrer')
    n.close()
  }
}

export function PolimarketRootProvider({
  children,
  active = true,
}: {
  children: ReactNode
  user?: unknown
  active?: boolean
}) {
  const [settings, setSettings] = useState<PolymarketSettings>(DEFAULT_SETTINGS)
  const [alerts, setAlerts] = useState<PolymarketAlert[]>([])
  const [latestEvents, setLatestEvents] = useState<Record<PolymarketCategory, PolymarketEvent[]>>({
    sports: [],
    esports: [],
  })
  const [isLoading, setIsLoading] = useState(false)
  const [lastCheckedAt, setLastCheckedAt] = useState<string | null>(null)
  const [lastError, setLastError] = useState<string | null>(null)
  const [notificationPermission, setNotificationPermission] = useState<
    NotificationPermission | 'unsupported'
  >('default')

  const seenRef = useRef<Set<string>>(new Set())
  const initializedRef = useRef(false)
  const pollingRef = useRef(false)

  useEffect(() => {
    setSettings(loadJson(STORAGE_SETTINGS, DEFAULT_SETTINGS))
    setAlerts(loadJson<PolymarketAlert[]>(STORAGE_ALERTS, []))
    seenRef.current = new Set(loadJson<string[]>(STORAGE_SEEN, []))

    if (typeof window !== 'undefined' && 'Notification' in window) {
      setNotificationPermission(Notification.permission)
    } else {
      setNotificationPermission('unsupported')
    }
  }, [])

  const persistSettings = useCallback((next: PolymarketSettings) => {
    setSettings(next)
    saveJson(STORAGE_SETTINGS, next)
  }, [])

  const updateSettings = useCallback(
    (patch: Partial<PolymarketSettings>) => {
      persistSettings({ ...settings, ...patch })
    },
    [persistSettings, settings],
  )

  const persistAlerts = useCallback((next: PolymarketAlert[]) => {
    setAlerts(next)
    saveJson(STORAGE_ALERTS, next)
  }, [])

  const persistSeen = useCallback((seen: Set<string>) => {
    seenRef.current = seen
    saveJson(STORAGE_SEEN, Array.from(seen))
  }, [])

  const processEvents = useCallback(
    (data: Record<PolymarketCategory, PolymarketEvent[]>) => {
      setLatestEvents(data)

      const newAlerts: PolymarketAlert[] = []
      const nextSeen = new Set(seenRef.current)
      const categories: PolymarketCategory[] = ['sports', 'esports']

      const categoryEnabled: Record<PolymarketCategory, boolean> = {
        sports: settings.notifySports,
        esports: settings.notifyEsports,
      }

      for (const category of categories) {
        if (!categoryEnabled[category]) continue

        for (const event of data[category]) {
          const key = eventKey(category, event.id)
          if (nextSeen.has(key)) continue

          nextSeen.add(key)

          if (initializedRef.current) {
            newAlerts.push({
              id: `${key}-${Date.now()}`,
              eventId: event.id,
              title: event.title,
              slug: event.slug,
              category,
              image: event.image || event.icon,
              createdAt: event.createdAt,
              detectedAt: new Date().toISOString(),
              read: false,
            })
          }
        }
      }

      persistSeen(nextSeen)
      initializedRef.current = true

      if (newAlerts.length > 0) {
        setAlerts((prev) => {
          const merged = [...newAlerts, ...prev].slice(0, 100)
          saveJson(STORAGE_ALERTS, merged)
          return merged
        })

        if (settings.browserNotifications) {
          for (const alert of newAlerts) {
            sendBrowserNotification(alert)
          }
        }
      }
    },
    [persistSeen, settings.browserNotifications, settings.notifyEsports, settings.notifySports],
  )

  const refreshNow = useCallback(async () => {
    if (pollingRef.current) return
    pollingRef.current = true
    setIsLoading(true)
    setLastError(null)

    try {
      const data = await fetchAllCategoryEvents(50)
      processEvents(data)
      setLastCheckedAt(new Date().toISOString())
    } catch (err) {
      setLastError(err instanceof Error ? err.message : 'Error desconocido')
    } finally {
      setIsLoading(false)
      pollingRef.current = false
    }
  }, [processEvents])

  useEffect(() => {
    if (!active || !settings.monitoring) return

    refreshNow()
    const timer = setInterval(refreshNow, settings.pollIntervalMs)
    return () => clearInterval(timer)
  }, [active, refreshNow, settings.monitoring, settings.pollIntervalMs])

  const markAlertRead = useCallback(
    (id: string) => {
      persistAlerts(alerts.map((a) => (a.id === id ? { ...a, read: true } : a)))
    },
    [alerts, persistAlerts],
  )

  const markAllRead = useCallback(() => {
    persistAlerts(alerts.map((a) => ({ ...a, read: true })))
  }, [alerts, persistAlerts])

  const clearAlerts = useCallback(() => {
    persistAlerts([])
  }, [persistAlerts])

  const requestNotificationPermission = useCallback(async () => {
    if (typeof window === 'undefined' || !('Notification' in window)) {
      setNotificationPermission('unsupported')
      return 'denied' as NotificationPermission
    }

    const permission = await Notification.requestPermission()
    setNotificationPermission(permission)
    return permission
  }, [])

  const unreadCount = alerts.filter((a) => !a.read).length

  return (
    <PolimarketCtx.Provider
      value={{
        settings,
        updateSettings,
        alerts,
        unreadCount,
        markAlertRead,
        markAllRead,
        clearAlerts,
        latestEvents,
        isLoading,
        lastCheckedAt,
        lastError,
        refreshNow,
        requestNotificationPermission,
        notificationPermission,
      }}
    >
      {children}
    </PolimarketCtx.Provider>
  )
}

export function usePolimarket(): PolimarketContextValue {
  const ctx = useContext(PolimarketCtx)
  if (!ctx) {
    throw new Error('usePolimarket must be used within PolimarketRootProvider')
  }
  return ctx
}

'use client'

import { useEffect, useRef, useCallback, useState } from 'react'
import { supabase } from '@/lib/supabase/client'
import type { RealtimeChannel } from '@supabase/supabase-js'

export type RemotePlayerState = {
  id: string
  name: string
  position: [number, number, number]
  rotation: number // yaw angle
  health: number
  action: string
  timestamp: number
}

export type DamageEvent = {
  fromId: string
  fromName: string
  toId: string
  damage: number
}

type MultiplayerState = {
  remotePlayers: Map<string, RemotePlayerState>
  sendState: (state: Omit<RemotePlayerState, 'timestamp'>) => void
  sendDamage: (event: DamageEvent) => void
  onDamage: (callback: (event: DamageEvent) => void) => () => void
  health: number
  setHealth: (h: number) => void
  maxHealth: number
}

export function useMultiplayer(userId: string, userName: string): MultiplayerState {
  const channelRef = useRef<RealtimeChannel | null>(null)
  const [remotePlayers, setRemotePlayers] = useState<Map<string, RemotePlayerState>>(new Map())
  const [health, setHealth] = useState(100)
  const damageCallbacks = useRef<Set<(e: DamageEvent) => void>>(new Set())
  const maxHealth = 100

  const sendState = useCallback(
    (state: Omit<RemotePlayerState, 'timestamp'>) => {
      if (!channelRef.current) return
      channelRef.current.send({
        type: 'broadcast',
        event: 'player_state',
        payload: { ...state, timestamp: Date.now() },
      })
    },
    [],
  )

  const sendDamage = useCallback(
    (event: DamageEvent) => {
      if (!channelRef.current) return
      channelRef.current.send({
        type: 'broadcast',
        event: 'player_damage',
        payload: event,
      })
    },
    [],
  )

  const onDamage = useCallback((callback: (event: DamageEvent) => void) => {
    damageCallbacks.current.add(callback)
    return () => {
      damageCallbacks.current.delete(callback)
    }
  }, [])

  useEffect(() => {
    if (!userId) return

    const channel = supabase.channel('tps-game', {
      config: { broadcast: { self: false } },
    })

    channel
      .on('broadcast', { event: 'player_state' }, ({ payload }) => {
        const state = payload as RemotePlayerState
        if (state.id === userId) return
        setRemotePlayers((prev) => {
          const next = new Map(prev)
          next.set(state.id, state)
          return next
        })
      })
      .on('broadcast', { event: 'player_damage' }, ({ payload }) => {
        const event = payload as DamageEvent
        if (event.toId === userId) {
          setHealth((prev) => Math.max(0, prev - event.damage))
        }
        for (const cb of damageCallbacks.current) {
          cb(event)
        }
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          channelRef.current = channel
        }
      })

    const cleanupInterval = setInterval(() => {
      setRemotePlayers((prev) => {
        const now = Date.now()
        const next = new Map(prev)
        let changed = false
        for (const [id, state] of next) {
          if (now - state.timestamp > 10000) {
            next.delete(id)
            changed = true
          }
        }
        return changed ? next : prev
      })
    }, 2000)

    return () => {
      channel.unsubscribe()
      supabase.removeChannel(channel)
      clearInterval(cleanupInterval)
    }
  }, [userId])

  return {
    remotePlayers,
    sendState,
    sendDamage,
    onDamage,
    health,
    setHealth,
    maxHealth,
  }
}

